programs.sol:
"""Document onset, with a few sharp spelling-boundary responses.

The positive onset estimate lasts through a run of identical initial tokens.
Its size depends on script, capitalization, and formatting. A colon
immediately after the initial Title token has a large negative response. Elsewhere, the explicit rules
cover Arabic ta-hamza, Russian сформ, Malay sambil, and uppercase LIST/SIZE
split after their first letter; other text gets a small background value.
These are spelling rules, not a general detector of the words' meanings.
"""
import re
import unicodedata

READS = ()


def onset(token):
    text = token.strip()
    if token == '<|im_start|>':
        return 1.247
    if not text:
        return 0.49
    if text.isdigit():
        return 0.60
    letter = next((c for c in text if c.isalpha()), '')
    if not letter:
        return 0.19 if '\n' in token else 0.54
    script_name = unicodedata.name(letter, '')
    if 'CJK' in script_name:
        return 0.62
    if 'LATIN' in script_name:
        if token[0].isspace():
            return 0.68 if letter.isupper() else 0.73
        return 1.01 if letter.isupper() else 0.82
    return 0.90


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token_id = prefix.token_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        initial_token, position, previous = token_id, 0, ''
    else:
        _, initial_token, position, previous = carry
        position = min(position + 1, 2)
        if token_id != initial_token:
            initial_token = None

    value = onset(token) if initial_token is not None else -0.005
    if position == 1 and previous == 'Title' and token == ':':
        value = -3.397
    elif token == 'أ' and previous.strip() in {'ت', 'الت'}:
        value = 0.98
    elif token == 'форм' and previous.strip().lower() == 'с':
        value = -0.66
    elif token == 'ambil' and re.search(r'(?:^|[^A-Za-z])s$', previous):
        value = -0.60
    elif ((token == 'IST' and re.search(r'(?:^|[^A-Za-z])L$', previous))
          or (token == 'IZE' and re.search(r'(?:^|[^A-Za-z])S$', previous))):
        value = 0.64
    return (doc, initial_token, position, token), value

programs.haiku:
"""Document-opener detector for layers.1.mlp.down_proj:4032.

This component is silent almost everywhere. Its job is at the first token of each
document, the token right after <|endoftext|> (or the first token of a packed row).
There it writes a positive value: about +0.9 when the opener is a word, +1.2 for a
special token such as <|im_start|>, +0.6 for a digit, +0.45 for a space, and +0.5
for other punctuation. Code and markup openers ('#include', '/*', '{') really come
out negative, which this rule does not capture.

Two more cases are singled out:
- the colon right after a document-initial "Title" (as in "Title: ...") gets a
  strongly negative value, about -3.4, the component's largest response;
- the repeated middle-dot filler token '··' gets about -0.6.

Everywhere else the program predicts 0. The small diffuse activations elsewhere
(std about 0.04) are not captured by any simple rule.

A document start is a token whose document id differs from the previous token's,
or the first token of the row (carry is None there).
"""

READS = ()

DOT_FILLER = "··"


def opener_value(token: str) -> float:
    """How strongly the first token of a document activates the component."""
    core = token.strip()
    if not core:
        return 0.45
    first = core[0]
    if first.isalpha():
        return 0.9
    if first.isdigit():
        return 0.6
    if first == "<":
        return 1.2
    return 0.5


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == DOT_FILLER:
        return None, -0.6
    if prefix.position == 0:
        return None, opener_value(token)
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, opener_value(token)
    # Position 1 of a document: the colon in "Title: ..." right after the opener "Title".
    if token == ":" and prefix.position >= 1 and prefix.token_strings[-2] == "Title":
        if prefix.position == 1 or prefix.document_ids[-3] != prefix.document_ids[-2]:
            return None, -3.4
    return None, 0.0

programs.sol:
"""A sparse lexical approximation, with separate document-opening effects.

Opening code keywords and the opening numeral prefix 12 have strong responses.
Later cues include marital status, the remaining/damaged morpheme, application
requirements and exam cards. A structural-body suffix is negative. Initial
or consecutive middle-dot/four-caret markers are positive; backticks negative.
Smaller opening corrections use English word classes and case. Other text
stays near zero. These are several triggers, not one proposed semantic theme.
"""
from functools import lru_cache
import regex
import cedict
from opencc import OpenCC

SIMPLIFY = OpenCC('t2s')

READS = ()
ARTICLES = {'a', 'an', 'the'}
PREPOSITIONS = {'to', 'in', 'on', 'at', 'by', 'for', 'from', 'with', 'of'}
PRONOUNS = {'i', 'we', 'you', 'he', 'she', 'it', 'they'}


@lru_cache(maxsize=8192)
def gloss(s):
    return ' '.join(cedict.glosses(s)).lower()


@lru_cache(maxsize=16384)
def lexical(text, previous):
    s = text.strip()
    if s and set(s) == {'`'}:
        return -0.05
    if not regex.fullmatch(r'\p{Script=Han}+', s):
        return 0.0
    s = SIMPLIFY.convert(s)
    p = SIMPLIFY.convert(previous.strip())
    if s == '残':                         # remaining / damaged morpheme
        return 0.85
    if s == '婚':                         # bound marriage morpheme
        return 2.5
    g = gloss(s)
    phrase = gloss(p + s)
    if '婚' in s:
        if regex.search(r'\b(marry|married|unmarried|divorce)\b', g):
            return 1.25                   # marital state, not wedding ceremony
        return 0.65 if 'marriage' in g or 'matrimony' in g else 0.0
    if s == '体' and p.endswith(('基', '主', '结构')):
        return -1.1                      # base/main/structural body suffix
    value = 0.0
    if regex.search(r'\b(qualified|eligible)\b', g + ' ' + phrase):
        value += 1.3
    elif regex.search(r'\bqualifications?\b', g):
        value += 0.15
        if regex.search(r'\b(apply|application|conform|meet)\b', gloss(p)):
            value += 1.1                 # application / conformity requirements
    if 'academic subject' in g:
        value += 0.5
    if 'admission ticket' in phrase:
        value += 1.0                     # examination admission card
    elif 'certificate' in g:
        value += 0.1
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, opening = 0, text
    else:
        _, position, opening = carry
    state = (doc, position + 1, opening)
    previous = prefix.token_strings[-2] if position else ''
    value = -0.002 + lexical(text, previous)
    if len(text) >= 2 and set(text) == {'·'}:
        value = 0.54 if position == 0 or previous == text else 0.0
    if text == '^^^^' and (position == 0 or previous == text):
        value = 1.51
    if position == 0:
        if text in {'package', 'import'}:
            return state, -1.105
        if text == 'def':
            return state, 2.145
        if text in {'int', 'float', 'double', 'long', 'void'}:
            return state, 2.0
        if text in {'const', 'let', 'var', 'class'}:
            return state, -0.8
        if text.lower() == 'see':
            return state, 1.5
        if text == 'with':
            return state, 1.057
        s = text.strip()
        value -= 0.16 * (s.isascii() and s.istitle())
        value -= 0.28 * (s.lower() in ARTICLES)
        value += 0.14 * (s.lower() in PREPOSITIONS)
        value += 0.31 * (s.lower() in PRONOUNS)
        value += 0.18 * text.isspace()
    elif position == 1:
        if opening == 'package' and text == ' com':
            value = 1.961
        elif opening == '1' and text == '2':
            value = 2.877
    return state, float(value)

"""Approximate a signed local English phrase feature.

Positive: noun compounds with an -ing modifier, especially rooms, points
and substances; personal names; physical and mathematical expressions.
Negative: ordinal selections and spatial descriptions. Constants approximate
training means; the component's remaining lexical variation is not modeled.
Carry only the trailing English word, resetting at document boundaries.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
ORDINAL = set('''
first second third fourth fifth sixth seventh eighth ninth tenth last next
'''.split())
SPATIAL = set('''
top bottom upper lower front rear back left right middle inner outer
north south east west northern southern eastern western
'''.split())
LAYOUT = set('''
surface side wall end edge face corner row direction view line part case level
'''.split())
DEGREE = set('''
most least more less greatest smallest largest highest lowest maximum minimum
maximal minimal nearest
'''.split())
COMPARATIVE = set('''
high low higher lower highest lowest longest shortest larger smaller bigger
longer shorter
'''.split())
QUANTITIES = {
    'molecular weight', 'refractive index', 'specific heat', 'specific gravity',
}


@lru_cache(maxsize=100000)
def phrase_value(previous, token):
    a, b = previous.lower(), token.lower().lstrip('-_')
    if not a.isalpha() or not b.isalpha():
        return 0.0
    nouns = wordnet.base_forms(b, 'noun')
    head = next((w for w in nouns if w != b), b)
    if a == 'each' and head == 'other':
        return 1.05
    if head == 'name':
        names = {'given': 3.15, 'first': 1.4, 'last': 1.5, 'middle': 0.5}
        if a in names:
            return names[a]
    if ((a in {'first', 'second'} and head == 'language')
            or (a == 'first' and head == 'floor')):
        return 3.2
    if head == 'possible':
        if a == 'best':
            return 4.0
        if a in DEGREE:
            return 2.7
    if a + ' ' + head in QUANTITIES:
        return 3.0
    if a == 'most' and head in {'common', 'commonly'}:
        return 1.35
    if a in {'upper', 'lower'} and head in {'limit', 'bound'}:
        return 2.0
    if (head == 'order'
            and a in {'increasing', 'decreasing', 'ascending', 'descending'}):
        return 3.1
    activity = a.endswith('ing')
    if activity and head == 'point':
        return 3.0
    if activity and head == 'room':
        return 2.9
    if head == 'state':
        if a == 'ground':
            return 5.0
        if a == 'steady':
            return 2.65 if token[:1].isupper() else 0.7
        if a in {'excited', 'resting'}:
            return 3.3
    if a in ORDINAL:
        if head in {'one', 'of'}:
            return -1.7
        if (head in LAYOUT or head in {
                'person', 'people', 'period', 'edition', 'term', 'pair',
                'question'}):
            return -0.73
        if nouns:
            return -0.17
    if a in SPATIAL:
        if head in LAYOUT:
            return -0.72
        if nouns:
            return -0.08
    if a in COMPARATIVE and (nouns or 'adjective' in wordnet.parts_of_speech(b)):
        return -0.14
    compound = a + ' ' + b
    if 'noun' in wordnet.parts_of_speech(compound):
        if activity:
            if 'noun.substance' in wordnet.categories(compound):
                return 2.3
            return 0.48
        return 0.04
    return 0.045 if activity and nouns else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = phrase_value(previous, token.strip())
    trailing = re.search(r'[A-Za-z]+$', previous + token)
    return (doc, trailing[0] if trailing else ''), value

"""Negative pulses for short nasal/stop rhymes, especially in word fragments.

The rule joins the current token to the preceding word fragment, so 'Num' +
'Py' and 'skip' + 'per' are recognizable spellings. Common complete words
are suppressed by an English word-frequency check. Pink gets a strong
lexical response. Katakana N+K/P/CH spellings and repeated middle dots
get separate negative estimates.
This is an orthographic approximation, not a pronunciation model.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
RHYMES = re.compile(r'ump|ink|unk|imp|amp|emp|omp|ipp|umm|[aeiou]nc|[aeo]nk')
TRAILING = re.compile(r'[A-Za-z-]+$')


@lru_cache(maxsize=32768)
def predict(previous, token):
    stripped = token.strip()
    if stripped and set(stripped) == {'·'} and len(stripped) > 1:
        return -0.7
    if not stripped or not stripped[0].isalpha():
        return 0.0
    fragment = bool(previous) and token[0].isalpha()
    word = (previous + token if fragment else stripped).lower()
    boundary = len(previous) if fragment else 0
    if stripped.lower() == 'pink':
        return -5.5 if stripped[0].isupper() else -3.5
    matches = list(RHYMES.finditer(word))
    matches = [m for m in matches if m.end() >= boundary - 1]
    if not matches:
        return 0.0
    m = matches[-1]
    rhyme = m.group()
    after = word[m.end():]
    onset = word[:m.start()]
    liquid = onset.endswith(('l', 'r'))
    # Does this token begin at the rhyme vowel, or split its consonants?
    starts_rhyme = m.start() == boundary
    consonant_onset = bool(onset) and not any(c in 'aeiou' for c in onset)
    crossing = m.start() < boundary < m.end()
    suffix = after in ('er', 'ers', 'ered', 'ering', 'le', 'les', 'led',
                       'y', 'kin', 'kins', 'en', 'ings', 'ie')

    if rhyme == 'ump':
        if not fragment:
            if after.startswith('kin'):
                strength = 4.2
            elif onset == 'l' and (suffix or not after):
                strength = 4.2
            elif after in ('er', 'ers'):
                strength = 2.5
            else:
                strength = 2.2 if liquid and suffix else 0.6
        elif starts_rhyme:
            strength = 6.5 if liquid else 2.0
        elif crossing:
            strength = 4.5 if not onset.endswith(('f', 's', 'h')) else 0.3
        else:
            strength = 2.3 if suffix or after in ('ed', 's') else 0.1
    elif rhyme == 'ink':
        if fragment and starts_rhyme:
            strength = 4.0 if consonant_onset else 0.3
        elif fragment:
            strength = 1.8 if suffix else 0.15
        else:
            strength = 2.0 if suffix else 0.25
    elif rhyme == 'imp':
        strength = 0.05
        if crossing:
            strength = 3.2
        elif starts_rhyme and consonant_onset and not after:
            strength = 2.0
        if not onset:
            strength *= 0.25
    elif rhyme == 'ipp':
        strength = 4.0 if crossing and after in ('er', 'ers', 'ered') else 0.05
        if strength == 4.0 and onset.endswith('sk'):
            strength = 6.0
    elif rhyme == 'umm':
        strong = fragment and starts_rhyme and after in ('er', 'ers')
        strength = 5.8 if strong else 0.05
    elif rhyme == 'unk':
        strength = 2.5 if fragment and suffix else 0.25
    elif rhyme in ('amp', 'emp', 'omp'):
        strength = 2.5 if crossing and after in ('er', 'ers', 'ered') else 0.15
    else:
        if crossing and rhyme.endswith('nk'):
            strength = 2.0 if after in ('er', 'ers', 'en') else 0.6
        elif crossing and after.startswith(('ker', 'her')):
            strength = 2.5
        else:
            strength = 0.02
    if sum(c in 'aeiou' for c in after) > 1 and not suffix:
        strength *= 0.15
    frequency = zipf_frequency(word, 'en')
    if frequency >= 4.5:
        strength *= 0.15
    return -strength


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    reset = carry is None or carry[0] != document
    previous = '' if reset else carry[1]
    previous_token = '' if reset else carry[2]
    token = prefix.token_strings[-1]
    value = predict(previous, token)
    # Katakana N followed by K/P/CH, e.g. ラン + ク.
    if (previous_token.endswith('ン') and token
            and token[0] in 'カキクケコパピプペポチ'):
        value = -2.7 / max(1, len(token))
    match = TRAILING.search(previous + token)
    tail = match.group()[-24:] if match else ''
    return (document, tail, token), value

"""Approximate a context-sensitive 'to' signal and a document-opening response.

The spaced word 'to' gets a larger value after ordinary nouns or objects,
and a smaller one in tight combinations like 'want to' or 'equal to'.
Rules use the preceding word's grammatical class and familiar collocations.

Opening rules distinguish articles, pronouns, declarations, punctuation,
and numbers; the measured negative opening response is strongest for 4-8.
They also apply to uninterrupted repetitions of the opening token. Other
positions are zero except for standalone 'to' variants. Arbitrary opening
words and fragments are deliberately not memorized.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

CONTROL = set('need needs needing want wants wanted wanting have has had '
              'trying able unable ready supposed meant'.split())
RELATION = set('according due equal equals equivalent related relating relates '
               'relate relative respect prior next close closer adjacent '
               'similar comparable compared corresponding corresponds '
               'correspond opposed subject subjected referred referring '
               'refers refer leading leads lead led limited entitled'.split())
MOTION = set('go goes went come comes came return returns returned returning '
             'belong belongs belonging convert converted reduced'.split())
COMPLEMENT = set('try tried decide decided seems seem seemed likely possible '
                 'expected intended prepared wish how ability desire'.split())
RELATION_NOUNS = set('ability capacity attempt attention reference response '
                     'respect addition comparison connection commitment '
                     'contribution'.split())
DECLARATIONS = set('def function class import export int const var'.split())
OBJECTS = set('it me you him her us them which what that'.split())
PASSIVE = set('used required needed applied added failed fails chosen '
              'elected considered selected'.split())

@lru_cache(maxsize=8192)
def parts(word):
    return wordnet.parts_of_speech(word)


def to_signal(previous):
    words = re.findall(r"[\w']+|[^\s\w]", previous.lower())
    w = words[-1] if words else ''
    if any(ord(ch) > 127 and ch.isalpha() for ch in w):
        return -0.15
    if w in CONTROL:
        return -0.09
    if w in RELATION:
        return -0.055
    if w in MOTION:
        return -0.17
    if w in COMPLEMENT:
        return 0.04
    if w in RELATION_NOUNS:
        return 0.12
    if w in OBJECTS:
        return 0.40
    if w in PASSIVE:
        return 0.39
    if w in {'order', 'together', 'here', 'time'}:
        return 0.59
    if w in {'up', 'way', 'going', 'as'}:
        return 0.08
    if w in {'is', 'are', 'was', 'were', 'be', 'been'}:
        return 0.07
    if w in {'and', 'or', 'not', ',', ')', '`'}:
        return 0.30
    pos = parts(w)
    if 'noun' in pos:
        return 0.40
    if 'adjective' in pos or w.endswith('ing'):
        return 0.21
    if 'verb' in pos:
        return 0.27
    if w.isdigit():
        return 0.0
    return 0.24


def opening(token):
    s = token.strip()
    w = s.lower()
    if not s:
        return 1.5 if '\n' in token or '\t' in token else -0.4
    if s.isdecimal():
        return -3.0 if len(s) == 1 and s in '45678' else -0.1
    if w == 'the':
        return 2.3
    if w == 'an':
        return 3.7 if token != 'an' else 1.0
    if w == 'a':
        return 1.3 if token == ' a' else -0.3
    if w in {'i', 'you', 'we', 'he', 'she', 'my', 'your'}:
        return 1.9
    if w in {'to', 'for', 'at'}:
        return 2.0 if w == 'to' else 1.3
    if w in {'in', 'on', 'into', 'between', 'about', 'this', 'that', 'those'}:
        return -0.8
    if token.startswith(' ') and w in {
        'is', 'was', 'be', 'have', 'had', 'will', 'would', 'can', 'could'
    }:
        return 1.2
    if not any(ch.isalnum() for ch in s):
        if s in {',', ':', ')', '}', '|', '@'}:
            return 0.1
        return 1.65
    if w in DECLARATIONS:
        return 2.3
    if s.startswith('#'):
        return 1.6
    pos = parts(w)
    if 'adjective' in pos:
        return -0.55
    if 'verb' in pos or 'noun' in pos:
        return -0.35
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, first, uniform = '', token, True
    else:
        _, history, first, uniform = carry
        uniform = uniform and token == first
    if uniform:
        value = opening(token)
    elif token == ' to':
        value = to_signal(history)
    elif token.strip().lower() == 'to':
        value = 0.17 if token.strip() != 'to' or token.startswith(' ') else -0.2
    else:
        value = 0.0
    history = (history + token)[-120:]
    return (doc, history, first, uniform), value

programs.haiku:
"""layers.1.mlp.down_proj:4037 -- a 'location within a whole' detector on prepositions.

The component fires (positive) on the preposition in phrases that place something
inside, along or at a part, position or extent of a larger whole:
  "parts [of] the", "end [of] the", "point [in] space", "early [in] the",
  "stages [of]", "along", "throughout", "somewhere [in]", "[in] the" after a place.
It is negative on temporal modifiers ("last week", "next year", "first", "season")
and is weakly negative after quantity words ("one of", "any of", "rate of").
Plain 'in' / 'of' / 'on' get small positive values; most other tokens get 0.

Predicted activation at each token (the rules are checked in order):
  1. A preposition right after a part/position/location noun      -> 1.1
  2. A preposition after a quantity word ("one of", "rate of")     -> -0.1
  3. A preposition after a verb-like word (-ed / -ing)            -> 0
  4. "along" / "throughout"                                       -> 1.0
  5. "in" after a plural noun -> 0.45, other "in" -> 0.1;
     "of" after a plural noun -> 0.25, other "of" -> 0.05; "on" -> 0.18
  6. "the" after "of" that follows a part noun -> 0.9; after "in" or a
     spatial preposition (across, within, through, ...) -> 0.8; after "of" -> 0.12
  7. Temporal modifiers (last, next, first, week, year, season, ...) -> -0.36
  8. Everything else -> 0
A document boundary resets the look-back, as the model's attention does.
"""

READS = ()

# Nouns for a part, position, place or extent within a whole (plus "early/later" in a sequence).
PART_NOUNS = {
    " part", " parts", " portion", " portions", " piece", " pieces", " section", " sections",
    " stage", " stages", " step", " steps", " half", " edge", " edges", " end", " ends",
    " side", " sides", " area", " areas", " region", " regions", " point", " points",
    " element", " elements", " member", " members", " column", " columns", " row", " rows",
    " top", " bottom", " place", " aspect", " level", " levels", " spot", " spots",
    " corner", " corners", " location", " locations", " branch", " branches", " group",
    " groups", " page", " sheet", " sheets", " node", " nodes", " early", " later",
    " somewhere", " anywhere", " everywhere", " where",
}
QUANTITY = {
    " one", " any", " many", " each", " rate", " total", " loss", " success", " case",
    " number", " amount", " lot", " some", " kind", " type", " sum", " deviation",
    " frequency", " intensity", " order", " importance", " average",
}
TEMPORAL = {
    " week", " season", " year", " month", " day", " night", " morning", " last", " next",
    " first", " previous", " earlier",
}
SPATIAL = {
    " along", " across", " throughout", " within", " inside", " around", " during",
    " through", " over", " among",
}
PREPS = {" of", " in", " on", " at", " into"} | SPATIAL


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    n = len(prefix)
    same1 = n > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    same2 = n > 2 and prefix.document_ids[-3] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same1 else ""
    prev2 = prefix.token_strings[-3] if same2 else ""
    word = prev.strip()
    if cur in PREPS:
        if prev in PART_NOUNS:
            value = 1.1
        elif prev in QUANTITY:
            value = -0.1
        elif word.endswith("ed") or word.endswith("ing"):
            value = 0.0
        elif cur in {" along", " throughout"}:
            value = 1.0
        elif cur == " in":
            value = 0.45 if word.endswith("s") else 0.1
        elif cur == " of":
            value = 0.25 if word.endswith("s") else 0.05
        elif cur == " on":
            value = 0.18
        else:
            value = 0.05
    elif cur == " the":
        if prev == " of" and prev2 in PART_NOUNS:
            value = 0.9
        elif prev == " in" or prev in SPATIAL:
            value = 0.8
        elif prev == " of":
            value = 0.12
        else:
            value = 0.0
    elif cur in TEMPORAL:
        value = -0.36
    else:
        value = 0.0
    return None, float(value)

