"""A sparse negative lexical response, strongest on Chinese 其 ('its/their').

Smaller responses cover two-character tokens ending in 其, archaic 厥,
Japanese その, Korean 그, and the phonetic neighbours 奇 and 기.
Word frequencies in recent text distinguish Spanish su/sus from their
Italian/French uses. This is lexical, not a general possession detector.

UTF-8 fragments are joined across tokens; completing 其 or 奇 gives a
stronger response. Everything else gets a near-zero baseline. State resets
at document boundaries. Weak, token-specific onset effects are omitted.
"""
import codecs
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in ('es', 'it', 'fr', 'en'))


def spanish_context(text):
    words = re.findall(r'[^\W\d_]+', text.lower())[-18:]
    if not words:
        return False
    scores = [sum(frequencies(w)[i] for w in words) for i in range(4)]
    return scores[0] >= max(scores[1:])


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pending, recent = b'', ''
    else:
        _, pending, recent = carry
    raw = pending + prefix.token_bytes[-1]
    text, consumed = codecs.utf_8_decode(raw, 'ignore', False)
    word = text.strip()
    value = -0.001
    if word == '其':
        value = -9.5 if pending else -6.6
    elif len(word) == 2 and word.endswith('其'):
        value = -2.0 if word == '尤其' else -3.8
    elif word == '厥':
        value = -3.8
    elif word == '奇':
        value = -4.2 if pending else -3.2
    elif word == 'その':
        value = -2.25
    elif word == '그':
        value = -3.25
    elif word == '기':
        value = -1.25 if text.startswith(' ') else -0.75
    elif text in (' su', ' sus'):
        if spanish_context(recent):
            value = -1.6 if word == 'su' else -1.05
        else:
            value = 0.0
    return (doc, raw[consumed:], (recent + text)[-300:]), value

"""A lexical/spelling response centred on 'punch'.

Punch and its inflections give the largest response, including when split
between tokens. Similar p-vowel-ch/ck spellings and -unch rhymes respond
more weakly. Cyrillic and kana are transliterated for these spelling rules;
拳 (fist) is recognized directly. There are also small continuation and
compound-ending responses, and a negative response to middle-dot separators.
"""
from functools import lru_cache
import regex as re
from anyascii import anyascii

READS = ()

# Contributions for a spelling within one token or spanning a token boundary.
SPELLINGS = (
    (r'puch', 0.0, 2.8),
    (r'pouch', 2.0, 4.1),
    (r'puck', 4.3, 3.2),
    (r'peck', 0.0, 2.7),
    (r'peach', 1.5, 3.7),
    (r'p[aeiou](?:n|l|t)?ch|p(?:oo)ch', 0.16, 1.57),
    (r'punct?', 1.4, 2.6),
)


@lru_cache(maxsize=8192)
def spelling(token):
    if re.search(r'\p{Cyrillic}|\p{Hiragana}|\p{Katakana}', token):
        token = anyascii(token)
    return token.lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    previous, current = spelling(old), spelling(token)
    joined = previous + current
    boundary = len(previous)
    p, s = previous.strip(), current.strip()

    def fresh(pattern):
        return next((m for m in re.finditer(pattern, joined)
                     if m.end() > boundary), None)

    value = 0.0
    punch = fresh('punch')
    if punch:
        if punch.start() < boundary:
            value = 11.1
        elif s != 'punch':
            value = 8.5
        else:
            value = 9.5 if token.strip().istitle() else 12.4
    elif 'punch' in p:
        value = 4.4 if s in ('up', '-ups') else 0.5

    for pattern, whole, split in SPELLINGS:
        match = fresh(pattern)
        if match:
            value += split if match.start() < boundary else whole

    if not punch and s.startswith('unch') and re.search(r'(cr|b)$', p):
        value += 4.1
    if s.startswith(('bunch', 'crunch', 'scrunch', 'munch')):
        value += 1.4
    if s in ('out', 'house', 'houses') and re.search(r'p[a-z]*$', p):
        value += 0.3 if s == 'out' else 1.9
    if '拳' in token:
        value += 8.0
    if token in ('チ', 'ツ'):
        value += 0.8 if old.endswith(('プ', 'パン')) else 0.1
    if token and set(token) <= {'·'}:
        value -= 0.95
    return (doc, token), value

"""Approximate the strong English distal-reference and nominal-quantity cues.

"Those" is strongly positive. For "that", local function words and action
verbs suggest a demonstrative, while noun/verb senses help keep clause-linking
uses small. "So ... that" is negative. Smaller rules cover nominal "need",
modified "number", and their following prepositions. These are lexical and
local grammatical heuristics, not a full parse; most other tokens get zero.
The short context resets at document boundaries and clears at sentence marks.
"""
from functools import lru_cache
import wordnet

READS = ()
PREPOSITIONS = set('of at for in to with on from into about after during '
                   'within by without before over under through upon '
                   'against beyond behind around between below above along '
                   'onto toward'.split())
SUBJECTS = set('i you he she it we they who'.split())
AUXILIARIES = set('can could will would shall should may might must '
                  'did does do have has had'.split())
DETERMINERS = set('the a an this these that those my your his her its '
                  'our their some any every each no'.split())
SIZES = set('large small huge vast considerable great greater higher lower '
            'maximum minimum maximal minimal total equal infinite '
            'increasing decreased increased growing'.split())
CHANGE = set('increase increasing increased increases reduce reduced reducing '
             'reduces decrease decreased decreasing limit limiting limits '
             'minimize minimizing enlarge'.split())
OBJECT_ACTIONS = set('do make use apply compute try get take give put keep '
                     'break lay handle continue avoid fix violate add change '
                     'repeat choose write'.split())

@lru_cache(maxsize=8192)
def verbs(word):
    return wordnet.base_forms(word, 'verb')

@lru_cache(maxsize=8192)
def pos(word):
    return wordnet.parts_of_speech(word)

@lru_cache(maxsize=8192)
def categories(word):
    return wordnet.categories(word)


def that_value(s, previous, before, history):
    p = previous.strip().lower()
    if p in PREPOSITIONS or p in {'like', 'as', 'than', 'since', 'because'}:
        if p in {'at', 'than', 'during', 'within'}:
            return 1.60
        if p == 'in':
            return 1.38 if previous.strip() == 'In' else 1.00
        return 1.28
    if p in {'if', 'when', 'what', 'how'}:
        return 1.65
    if p in {'but', 'then'}:
        return 1.10
    if p == 'and':
        return 1.15 if previous.strip() == 'And' else 0.47
    if p == 'so':
        return 0.85 if previous.strip() == 'So' else 0.23
    if p in {'maybe', 'perhaps'}:
        return 0.92
    if p == 'all':
        return 0.92
    if ',' in previous or ';' in previous:
        return 0.48
    if s.strip() == 'That':
        return 0.98 if not previous.strip().isalpha() else 0.05
    if p in {'is', 'are', 'was', 'were', 'be', 'been', 'being', 'am'}:
        return 0.05
    if p == 'such':
        return -0.14
    action = any(v in OBJECT_ACTIONS for v in verbs(p))
    if p == 'that' or (action and before not in DETERMINERS):
        return 1.10
    if p != 'so' and 'so' in history[-6:]:
        return -0.55
    senses = categories(p)
    if 'verb.communication' in senses:
        return -0.04
    if 'verb.cognition' in senses:
        return 0.12
    if 'adjective' in pos(p):
        return -0.15
    return -0.04


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, history, old_value = '', (), 0.0
    else:
        _, previous, history, old_value = carry
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    p = previous.strip().lower()
    before = history[-2] if len(history) > 1 else ''
    value = 0.0
    if w == 'those':
        value = 1.78
        if p in {'is', 'are', 'was', 'were', 'exactly', 'only'}:
            value = 1.05
    elif w == 'that':
        value = that_value(s, previous, before, history)
        if not previous:
            value = 0.69 if s.strip() == 'That' else 0.56
    elif w == 'these':
        value = -0.12 if previous.strip() == 'In' else 0.20
    elif w == 'this':
        value = -0.20 if previous.strip() == 'In' else -0.025
    elif w == 'need':
        if p == 'the':
            value = 1.95 if previous.strip() == 'the' else 1.15
            if any(t in {'without', 'eliminate', 'eliminating', 'remove',
                         'removing', 'avoid', 'avoiding'} for t in history[-4:]):
                value += 0.50
        elif p in SUBJECTS | AUXILIARIES or p.isdigit():
            value = 0.05
        elif p in {'a', 'an', 'no', 'my', 'your', 'his', 'her', 'our', 'their'}:
            value = 0.77
        elif p in {'this', 'that', 'these', 'those'}:
            value = 0.15
        elif 'adjective' in pos(p) and 'adverb' not in pos(p):
            value = 1.50 if before == 'the' else 0.65
        else:
            value = 0.045
    elif w in {'number', 'numbers'}:
        value = 0.14 if w == 'number' else 0.07
        if p in {'a', 'an', 'natural'}:
            value = -0.09
        elif p in SIZES:
            value = 0.60
        elif p == 'the':
            value = 0.34 if w == 'number' else 0.10
            if any(t in CHANGE for t in history[-5:]):
                value += 0.62
    elif w == 'of':
        if p in {'number', 'numbers', 'need'}:
            value = 0.65 * old_value + 0.05
        elif p in {'importance', 'necessity', 'urgency'}:
            value = 0.78
        elif p in {'ability', 'availability', 'potential', 'benefits',
                   'limitations', 'burden', 'millions', 'billions'}:
            value = 0.40
        elif p in {'amount', 'volume', 'quantity', 'thousands'}:
            value = 0.15
    elif w == 'for' and p == 'need':
        value = 0.55 * old_value
    if any(ch in s for ch in '.!?;\n'):
        history = ()
    elif w:
        history = (history + (w,))[-8:]
    return (doc, s, history, value), float(value)

