"""'that'/'those' used as demonstratives, plus a few quantity words and the preposition after them."""
READS = ()
THOSE = {' those', ' Those', 'Those', 'those'}
THAT = {' that', ' That', 'That', 'that'}
PREP = {' at', ' in', ' of', ' for', ' to', ' from', ' with', ' on', ' by', ' about', ' into',
        ' after', ' than', ' if', ' like', ' as', ' If', ' But', ' but', ' all', ' do'}
BOUNDARY = {'.', '.\n', '\n', ' So', 'So', ' But', ' And', ' In', ' At'}
MIDDLE = {',', ' and', ';'}
QUANTITY = {' number': 0.3, ' need': 0.2, ' these': 0.2, ' long': 0.25, ' large': 0.25,
            ' multiple': 0.25, ' vast': 0.25, ' diverse': 0.25}
# nouns that are usually followed by 'of', 'for' or 'on': 'the importance of', 'reliance on'
NOUN_PREP = {' importance', ' reliance', ' dependence', ' demand', ' potential', ' need',
             ' number', ' burden', ' ability', ' benefits', ' limitations', ' emphasis'}

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    same = len(prefix.token_strings) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]
    prev = prefix.token_strings[-2] if same else '.'
    if s in THOSE:
        v = 1.8
    elif s in THAT:
        if prev in PREP:
            v = 1.3
        elif prev in BOUNDARY:
            v = 1.0
        elif prev in MIDDLE:
            v = 0.5
        else:
            v = 0.0
    elif prev in NOUN_PREP and s in (' of', ' for', ' on'):
        v = 0.4
    else:
        v = QUANTITY.get(s, 0.0)
    return None, float(v)

programs.sol:
"""Approximate several local phrase, label and spelling responses.

Positive responses mark evidence/source prepositions, looking back, evaluative
adjective + 'to', and the initial word Title. Negative responses mark question
headings, isolated spaces after label words, initial 'Title:', and GEST/JEST
roots or suffixes. Everything else returns zero. Keep only 96 characters of
history, resetting at document boundaries; no later token is examined.
"""
import re

READS = ()
EVIDENCE = set('shown indicated demonstrated confirmed revealed '
               'suggested supported'.split())
INFERENCE = set('infer inferred conclude concluded determine determined '
                'learn learned understand understood see judged tell remember '
                'estimated appears visible viewed know assume'.split())
EVALUATION = set('important essential useful helpful reasonable natural '
                 'interesting logical imperative nice great advisable '
                 'appropriate correct fair indispensable preferable '
                 'realistic effective fantastic'.split())
LABELS = set('question lesson page chapter test step grade requirement '
             'section lecture scene stage part case assignment message option'.split())


def activation(token, before):
    s = token.strip()
    low = s.lower()
    previous = re.search(r'([A-Za-z]+)$', before)
    word = previous.group(1) if previous else ''
    w = word.lower()
    if not before and token == 'Title':
        return 1.05
    if token == ':' and before == 'Title':
        return -8.61
    if token == ' ':
        if word == 'Copyright':
            return -9.8
        if word in ('Question', 'Lesson'):
            return -3.4
        if w in LABELS:
            return -0.8
    if s == 'Question' and (not before or not before[-1].isalpha()
                            or token.startswith(' ')):
        return -1.8
    if token.startswith(' ') and low == 'questions':
        if w in ('these', 'following', 'guiding', 'important'):
            return 2.2
        return 0.15
    if token.startswith(' ') and low in ('by', 'from'):
        if low == 'from':
            if w == 'seen':
                if re.search(r'As (?:it )?can be seen$', before):
                    return 8.8
                return 4.8
            if w in ('clear', 'apparent', 'evident', 'obvious'):
                return 6.5
            if w in INFERENCE or w == 'view':
                return 3.0
        else:
            if w == 'evidenced':
                return 6.8
            if w == 'seen' and re.search(r'can (?:also )?be seen$', before):
                return 5.0
            if w == 'seen' or w in EVIDENCE:
                return 2.5
            if w.endswith('ed'):
                return 0.09
    if token.startswith(' ') and low == 'back':
        if w in ('look', 'looking', 'looked'):
            return 4.2
        if w == 'stand':
            return 0.5
    if token.startswith(' ') and low == 'to' and w in EVALUATION:
        return 1.0

    # GEST/JEST word families, including a root split across two tokens.
    if token == s and low.isalpha():
        if w == 'ing' and low.startswith('est'):
            return -8.5
        if w == 'in' and low.startswith('gest'):
            return -8.5
        if w == 'prog' and low.startswith('ester'):
            return -6.8
        if low == 'est' and w.endswith('maj'):
            return -2.2
        if low.startswith('est') and w.endswith('j') and not w.endswith('maj'):
            return -3.7
        if low.startswith('est') and w.endswith('g'):
            return -3.3
        if w == 'gest' and low.startswith(('ation', 'ational', 'ion', 'ión',
                                           'or', 'antes')):
            return -5.2
        if w == 'gestion':
            return -2.4
    if low.startswith('gestion'):
        return -5.0
    if low.startswith('ingest'):
        return -5.0
    if re.match(r'(?:con|di|e|re)?gest', low):
        return -1.5
    if 'jest' in low:
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = activation(token, before)
    return (doc, (before + token)[-96:]), value

programs.haiku:
"""layers.1.mlp.down_proj:4043 -- a 'code-syntax' detector that pushes negative.

This component's activation is near zero in ordinary prose and is strongly negative on
tokens that end or open a line of source code: a closing brace at the end of a line
(`}\\n`), a comment opener (`//`, `#`), a keyword or library call that starts a statement
(print, println, cout, import, include, fmt, ...), an opening brace or parenthesis at
line end, and statement ends (`;\\n`, `)\\n`). Assignment `=` and a call's opening
quote `('` are mildly negative. Everything else is treated as 0.

The numbers are the average activation of each class on sample text, rounded.
"""

READS = ()

KEYWORDS = {
    "print", "println", "printf", "fprintf", "cout", "console", "log", "fmt", "import",
    "include", "package", "public", "static", "namespace", "out", "Println", "main",
    "System", "std", "class", "func", "def",
}
COMMENT_OPENERS = {"//", "#", "/*", "/**", "*/", " */", "////////////////"}


def classify(tok):
    s = tok.strip()
    nl = "\n" in tok
    if s.lstrip(".").lstrip("#") in KEYWORDS or s in KEYWORDS:
        return "keyword"
    if s in COMMENT_OPENERS or s.startswith("//"):
        return "comment"
    if s.endswith("}") and nl:
        return "close_brace_nl"
    if s == "}":
        return "close_brace"
    if nl and s in ("{", "(", "[", ":"):
        return "open_nl"
    if s.endswith("('") or s == "('":
        return "call_quote"
    if nl and s in (";", ");", ")", "});", "};", "],", ")\n", ");\n"):
        return "stmt_nl"
    if s == "=" and tok.startswith(" "):
        return "assign"
    if nl and s == "":
        return "ws_nl"
    if nl:
        return "other_nl"
    return "other"


# Mean activation per class on sample text (see the docstring).
MEAN = {
    "close_brace_nl": -1.27, "comment": -0.87, "keyword": -0.56, "open_nl": -0.39,
    "stmt_nl": -0.31, "assign": -0.22, "call_quote": -0.40, "close_brace": -0.15,
    "other_nl": -0.09, "ws_nl": -0.07, "other": 0.0,
}


def step(carry, prefix, upstream):
    return carry, MEAN[classify(prefix.token_strings[-1])]

"""Layer 1, MLP down-projection component 4044: list-item and comment markers.

What it does: this component fires on the symbol that opens a bullet or list item, and on
comment leaders in code. Its main triggers, with typical activation:
  * a dash "-" (or " -") that starts a line: about 0.8 (strong, ~2x, when the line before
    ends with ":" and introduces a list; weaker, ~0.6x, when a bullet was just above it);
  * a bullet or star symbol that starts a line ("•", "*", "·", "・"): about 0.4-0.5;
  * the period of a numbered-list marker ("1." / "2." ... at line start): about 0.8 (2x after ":");
  * a comment leader "//" or "#" (mid-line after code ~0.6, at line start ~0.3-0.4);
  * a repeated middle dot "··" token: 2.5 (rare, but it dominates the variance when present).
Everything else is predicted as 0. Line starts are detected from the previous tokens, with
indentation skipped and a literal backslash-n counted as a line break.
Why: the component's variance is concentrated in these list and comment markers; a plain
rule captures about a fifth of the variance and most of the model-output effect.
"""
READS = ()

BULLETS = {"-": 0.8, " -": 0.9, "*": 0.5, "•": 0.5, "·": 0.4, "・": 0.4, "··": 2.5}
COMMENTS = {"//": 0.6, " //": 0.6, "#": 0.3, " #": 0.4, "///": 0.4, " ///": 0.4, "/*": 0.4}
BULLET_MARKS = ("-", "*", "•", "・", "·")


def line_start(toks):
    """True if the newest token opens a line (only indentation before it)."""
    j = len(toks) - 2
    while j >= 0 and toks[j] != "" and toks[j].strip(" \t") == "":
        j -= 1
    if j >= 1 and toks[j] == "n" and toks[j - 1] == "\\":
        return True
    return j < 0 or "\n" in toks[j]


def line_before(toks, end):
    """The token just before index `end`, skipping blank tokens."""
    j = end - 1
    while j >= 0 and toks[j].strip(" \t\n") == "":
        j -= 1
    return toks[j] if j >= 0 else ""


def list_intro(toks, end):
    """True if the line before index `end` ends with ':', introducing a list."""
    return line_before(toks, end).rstrip(" \t\n").endswith(":")


def prev_bullet(toks, window=40):
    """True if a list marker opened a line within the last `window` tokens."""
    for k in range(max(0, len(toks) - window), len(toks) - 1):
        if toks[k].strip(" \t") in BULLET_MARKS and k > 0 and "\n" in toks[k - 1]:
            return True
    return False


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    value = 0.0
    if cur in BULLETS and (line_start(toks) or cur == "··"):
        value = BULLETS[cur]
        if list_intro(toks, len(toks) - 1):
            value *= 2
        if prev_bullet(toks[:-1]):
            value *= 0.6
    elif cur in COMMENTS:
        value = COMMENTS[cur]
    elif cur == "." and len(toks) > 1 and toks[-2].isdigit() and line_start(toks[:-1]):
        value = 0.8
        if list_intro(toks, len(toks) - 2):
            value *= 2
    return carry, float(value)

programs.sol:
"""Approximate a signal for introducing possible actions and methods.

Score alternative markers, recommendations, and proposal constructions such
as "let me", "we can", and "a better way is to". A 220-character tail handles
purpose clauses and preceding words split across tokens. Small extra rules
cover list openings and some translated proposal words. Scores were fitted
on training rows; most tokens receive a value close to zero.
"""
import re

READS = ()
ALTERNATIVES = {
    'alternatively': 3.813,
    'perhaps': 2.401,
    'maybe': 2.108,
    'instead': 0.141,
}
METHODS = set(
    'approach method way solution idea strategy option trick '
    'technique procedure'.split()
)
EVALUATIONS = set(
    'better best easier easiest simpler simplest preferable advisable safer '
    'advantageous helpful important necessary essential useful convenient'.split()
)
PREFERRED = set('better best easier easiest simpler simplest preferable safer'.split())
QUALIFIERS = set(
    'another alternative different simpler simple better best easiest easier '
    'practical effective possible'.split()
)
PEOPLE = set('we i you one'.split())
MODALS = set('can could should must may might would'.split())
METHOD_TAIL = (
    r'\b(approach|method|way|solution|idea|strategy|option|step|goal|'
    r'objective|aim|purpose|task|plan)\b[^.!?;\n]{0,100}$'
)
MODIFIED_METHOD = r'\b(approach|method|way|solution|option) (would|could|may|might) be$'
EXTENDED_METHOD = (
    r'\b(one|another|the|a|an|alternative) (\w+ )?(way|solution|'
    r'approach|method|option)\b[^.!?;\n]{0,80} (is|be)$'
)
PURPOSE_MODAL = r'\b[Tt]o [^!?;\n]{3,210},\s*(you|we|I|one)\s*$'
INITIAL_PURPOSE_MODAL = r'\bTo [^!?;\n]{3,210},\s*(you|we|I|one)\s*$'


def predict(carry, token, doc):
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '')
    _, previous, before, tail = carry
    word = token.strip().lower()
