"""layers.1.mlp.down_proj:4045 -- "I am about to propose a way forward" detector.

This component fires on the word just BEFORE a proposed method, option or next step is
spelled out. Examples (activation in parentheses):
  "...the easiest way is [to] calculate"       (7.8)
  "It is better [to] say that"                 (6.4)
  "...[Alternatively], perhaps the ..."        (4.4)
  "...we need to.\\n\\n[Alternatively]"        (4.0)
  "To do that, [we] need"                      (3.5)
  "Let [me] try"                               (1.0)
  "you [can] use the"                          (~0.6 on average, up to 5)
It is near zero on most tokens, including the proposed method's own words.

This program makes the same guess from the words seen so far: a word-by-word table of how
strongly each cue word signals an upcoming proposal, with a few context rules (e.g. "to"
after "better" or "best" is strong; "to" after "need" is weak). Cues are English plus a
few common advice words in Chinese, Russian, Spanish and French. Predictions are in the
component's own activation units. It keeps no state across tokens."""

READS = ()

# Hedges that open an alternative or a suggestion, and their typical activation.
OPENERS = {"Alternatively": 3.9, "Perhaps": 2.7, "perhaps": 2.5, "Maybe": 2.6, "maybe": 2.2}

# Words that introduce advice or a method (English, Chinese, Russian, Spanish, French).
ADVICE = {
    "approach": 0.9, "Idea": 2.6, "idea": 0.8, "consist": 2.3, "consists": 0.9,
    "requires": 0.5, "consider": 0.5, "recommend": 0.8, "First": 0.5, "Or": 0.6,
    "最好": 3.3, "方法": 0.9, "建议": 1.0, "可以": 0.6, "можно": 1.3, "нужно": 1.6,
    "необходимо": 1.5, "стоит": 1.7, "лучше": 1.9, "можете": 1.9, "puedes": 2.4,
    "pouvez": 1.9, "faut": 2.0, "utilizar": 2.2,
}

# Nouns after which "is to ..." usually states a method or aim.
METHOD_NOUNS = {"way", "approach", "solution", "option", "idea", "method", "strategy", "aim",
                "purpose", "answer", "alternative", "goal", "key", "plan", "step"}
PLAN_VERBS = {"decided", "decide", "decides"}
# Verbs that, with "can"/"could"/"be" before them, lead into "... can be done by".
DONE_VERBS = {"done", "achieved", "accomplished", "calculated", "carried", "implemented",
              "solved", "computed", "performed", "obtained", "achieve", "accomplish", "solve"}


def step(carry, prefix, upstream):
    """Activation at the newest token, from its word and the words just before it."""
    words = [s.strip() for s in prefix.token_strings]
    t = len(words) - 1
    w = words[t]
    prev = words[t - 1] if t >= 1 else ""
    recent = set(words[max(0, t - 5):t])

    if w in OPENERS:
        return carry, OPENERS[w]
    if w in ADVICE:
        return carry, ADVICE[w]
    if w == "," and prev == "Alternatively":
        return carry, 2.5
    if w == "me" and prev == "Let":
        return carry, 1.0
    if w == "we" and prev == "So":
        return carry, 1.0
    if w == "we" and prev == ",":
        return carry, 0.7
    if w in ("can", "could", "should") and prev in ("we", "I", "you"):
        return carry, 1.2 if prev == "we" else 0.6
    if w == "by" and prev in DONE_VERBS and recent & {"can", "could", "be"}:
        return carry, 1.9
    if w == "to":
        if prev == "better":
            return carry, 6.0
        if prev == "best":
            return carry, 5.0
        if prev in ("is", "be"):
            return carry, 2.6 if recent & METHOD_NOUNS else 1.1
        if prev in PLAN_VERBS:
            return carry, 2.1
        if prev == "need":
            return carry, 0.9
        if prev == "want":
            return carry, 0.5
    return carry, 0.0

