"""Approximate an 'in / into' response, strongest in location/entry phrases.

The preceding word adjusts the response: copulas, getting, placement,
movement, pronouns and directional particles strengthen it. Longer words
and possible abstract-noun senses generally weaken it. Word endings also
contribute. WordNet supplies possible senses, not a contextual POS analysis.
Smaller fixed responses cover German/Russian location prepositions, English
entry words, and tokens containing Chinese entry characters. Other tokens
normally receive zero, with small document-initial offsets (larger for In).
History resets at document boundaries; there is no memorized bigram table.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
PLACEMENT = {'put', 'place', 'keep', 'hold', 'leave', 'remain', 'stay',
             'sit', 'stand', 'lie', 'lay', 'live', 'locate', 'situate'}
MOTION = {'go', 'come', 'walk', 'run', 'jump', 'move', 'fall', 'fly',
          'rush', 'bring', 'take', 'drive', 'step', 'turn', 'pull',
          'push', 'flow', 'lead', 'fit', 'throw', 'pour', 'climb'}
PRONOUNS = {'i', 'me', 'you', 'he', 'him', 'she', 'her', 'it', 'we',
            'us', 'they', 'them', 'myself', 'yourself', 'himself',
            'herself', 'itself', 'ourselves', 'themselves'}
PHYSICAL = {'noun.person', 'noun.body', 'noun.object', 'noun.artifact',
            'noun.animal', 'noun.plant', 'noun.food'}
ABSTRACT = {'noun.cognition', 'noun.communication', 'noun.attribute',
            'noun.quantity', 'noun.process'}


@lru_cache(maxsize=16000)
def phrase_value(word, into):
    """A small additive estimate from the preceding word's properties."""
    bases = set(wordnet.base_forms(word)) | {word}
    cats = wordnet.categories(word)
    value = (-2.5 if into else -1.5)
    value += (0.14 if into else 0.08) * min(12, len(word))
    if word in {'was', 'were'}:
        value += 0.2 if into else -2.1
    if word in {'am', 'is', 'are', "'m", "'re", '’m', '’re'}:
        value += -0.75 if into else -2.0
    if word in {'be', 'been', 'being'}:
        value += 0.0 if into else -1.7
    if word in {'get', 'gets', 'getting', 'got', 'gotten'}:
        value += -6.2 if into else -5.0
    if bases & PLACEMENT:
        value += -2.1 if into else -2.0
    if bases & MOTION:
        value += -2.7 if into else -1.3
    if word in {'not', "n't", 'n’t'}:
        value += -0.6 if into else -1.0
    if word in {'back', 'still', 'already', 'now'}:
        value += -2.2 if into else -1.7
    if word in {'born', 'married'}:
        value += 0.0 if into else -1.0
    if word in PRONOUNS:
        value += -0.2 if into else -1.0
    if word in {'up', 'out', 'down', 'away', 'off', 'over', 'along', 'around'}:
        value += -0.3 if into else -0.9
    if cats & PHYSICAL:
        value += -0.3 if into else -0.35
    if cats & ABSTRACT:
        value += 0.6 if into else 0.35
    if into and cats & {'noun.location', 'noun.time'}:
        value -= 0.4
    if into and cats & {'noun.state', 'noun.event', 'noun.act'}:
        value -= 0.3
    if word.endswith('ed'):
        value += 0.2 if into else 0.3
    if word.endswith('ing'):
        value += -0.6 if into else -1.0
    if word.endswith('ly'):
        value += -2.9 if into else -0.3
    if not any(ch.isalpha() for ch in word):
        value += 1.0 if into else 0.9
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0 if text else 0.14
    if token in {' in', ' into'}:
        match = re.search(r"([A-Za-z]+(?:['’][A-Za-z]+)?)\s*$", text)
        previous = match[1].lower() if match else text[-1:]
        value = phrase_value(previous, token == ' into')
    elif word.lower() == 'in':
        value = -0.3 if word == 'in' else -0.4
        if token == ' IN':
            value = -0.75
        if not text and token == 'In':
            value = 1.35
    elif word.lower() == 'into':
        value = -0.7 if word == 'Into' else 0.0
    elif token in {' im', ' Im', ' ins', ' Ins'}:
        value = -1.6 if word.lower() == 'ins' else -2.2
    elif token.lower() in {'-in', '_in', '-ins'}:
        value = -2.4
    elif word.lower() in {'enter', 'entered', 'entering', 'entry'}:
        value = -1.0
    elif token in {' в', ' В'}:
        value = -0.8 if word == 'в' else -0.5
    elif word and set(word) & set('入进進'):
        value = -0.8
    elif word == 'within':
        value = -0.1
    return (doc, (text + token)[-100:]), float(value)

"""A signed, spelling-dependent burst at the start of a context.

Capitalized copulas, other auxiliaries, and greetings get the largest positive
estimates. Other initial tokens are grouped by case, length, whitespace, and
English frequency. The estimate persists through an identical-token prefix;
a middle-dot leader is one strong example. A colon after initial "Title" gets
a negative correction. All other positions return zero. Word-specific variation
within these broad classes is deliberately not memorized.
"""
from functools import lru_cache
import unicodedata
from wordfreq import zipf_frequency

READS = ()
BE_FORMS = set("am is are was were be been being".split())
OTHER_AUXILIARIES = set(
    "do does did have has had can could will would shall should may might must".split()
)
GREETINGS = set("hello hi hey welcome dear greetings".split())


@lru_cache(maxsize=8192)
def initial_value(s):
    t = s.strip()
    if not t:
        return -0.21
    if len(t) >= 2 and set(t) == {'·'}:
        return 7.27
    space = bool(s[:1].isspace())
    if t[0].isupper():
        if space:
            return 0.64
        if len(t) == 1:
            return 1.95
        lower = t.lower()
        if lower in BE_FORMS:
            return 7.12
        if lower in OTHER_AUXILIARIES:
            return 3.92
        if lower in GREETINGS:
            return 4.28
        if zipf_frequency(t, 'en') > 5.8:
            return 0.15
        return 2.0 if len(t) <= 4 else 1.1
    if unicodedata.category(t[0])[0] in 'PS':
        return 0.48 if space else 0.03
    if t[0].islower():
        if not space and len(t) == 1:
            return 0.48
        return -1.09 if zipf_frequency(t, 'en') > 7.4 else -0.35
    return -0.32 if t[0].isdigit() else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        value = initial_value(text)
        return (doc, 0, token, text, True, value), value
    _, age, first, first_text, unchanged, value = carry
    age += 1
    unchanged = unchanged and token == first
    state = (doc, age, first, first_text, unchanged, value)
    if unchanged:
        return state, value
    if age == 1 and first_text == 'Title' and text == ':':
        return state, -9.41
    return state, 0.0

