"""Document-onset pulses, possessive endings, and indentation.

The first uninterrupted run of one token gets a type-based onset value,
usually negative, strongest for import headers and isolated Han characters.
Elsewhere, likely possessive apostrophes are positive: capitalized stems
get less than lowercase ones; common pronoun/'let' contractions are suppressed.
A single space following multi-space indentation gets a negative value.
Other positions default to zero; document boundaries reset the state.
"""
import re
import regex

READS = ()
CONTRACTION_STEMS = {
    'it', 'that', 'there', 'here', 'what', 'who', 'where', 'when', 'why',
    'how', 'he', 'she', 'let', 'this',
}


# Source-file declaration heads, with their different onset strengths.
MODULE_HEADERS = {
    'import': -10.3,
    'package': -7.4,
    'using': -4.8,
    'from': -4.1,
}


def onset(s, token_bytes):
    w = s.strip()
    if s in MODULE_HEADERS:
        return MODULE_HEADERS[s]
    if s.startswith('<|'):
        return -2.9
    if w and all(c == '·' for c in w):
        return -5.5
    if regex.search(r'\p{Script=Han}', s):
        return -5.6 if len(w) == 1 else -2.4
    if regex.search(r'\p{Script=Cyrillic}', s):
        return -2.55
    if '�' in s:
        # A bare continuation byte means the row begins inside a character.
        if s.startswith(' '):
            return -2.2
        if token_bytes and 0x80 <= token_bytes[0] < 0xC0:
            return -5.5
        return -3.7
    if s.isspace():
        if '\n' in s:
            return -1.8 if s == '\n' else -1.0
        return -0.75
    if '\n' in s:
        return -0.4
    if w.isdigit():
        return -2.6
    if w and all(c in '([{<' for c in w):
        return -1.0 if s.startswith(' ') else 0.6
    if w and all(c in ')]}>' for c in w):
        return -2.1
    return -1.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    tail, previous, initial_run = ('', '', True) if first else carry[1:]
    initial_run = first or (
        initial_run and prefix.token_ids[-1] == prefix.token_ids[-2]
    )
    value = onset(s, prefix.token_bytes[-1]) if initial_run else 0.0
    if not initial_run:
        match = re.search(r'([A-Za-z0-9_]+)$', tail)
        word = match.group(1) if match else ''
        possessive_s = s.lower() in {"'s", '’s'}
        if s.lower() == ';s' and tail.endswith(('&#39', '&apos')):
            possessive_s = True
            match = re.search(r'([A-Za-z0-9_]+)&(?:#39|apos)$', tail)
            word = match.group(1) if match else ''
        if possessive_s and word:
            if word.lower() not in CONTRACTION_STEMS:
                if word.lower() in {'today', 'yesterday', 'tomorrow', 'tonight'}:
                    value = 0.55
                elif word.isdigit():
                    value = 0.55
                else:
                    value = 0.8 if word[0].isupper() else 1.3
        elif (s in {"'", '’'} and word.lower().endswith('s')
              and len(word) > 2
              and word.lower() not in CONTRACTION_STEMS | {'was', 'has', 'yes'}):
            value = 1.5 if word[0].isupper() else 2.0
        elif (s == ' ' and len(previous) >= 2
              and not previous.strip(' \t')):
            value = -0.56 if len(previous) <= 4 else -0.41
    return (doc, (tail + s)[-64:], s, initial_run), value

