"""layers.1.mlp.down_proj:4050: a component that is strongly negative at the start of each
document (where it has no context) and positive on possessive 's.

What it does, in plain terms:
1. The first token of every document, or of a packed row, is written as a strongly negative
   value, sized by what the token looks like: code keywords such as `import` and `package`
   most negative, chat-control tokens such as `<|im_start|>` and CJK or other non-Latin
   scripts strongly negative, ordinary words around -1.5 to -2, and the comment openers `//`
   and `/*` positive.
2. A possessive apostrophe after a noun ('s or ’s, or a bare ' after a word ending in s, as in
   "Veterans' Appeals") is positive, about +1. A contraction after a pronoun (it's, that's,
   let's) is not.
3. The dotted-leader token '··' is strongly negative (-5.5).
4. A lone space that follows an indentation run is slightly negative (-0.5).
Everything else is 0.
"""

READS = ()

PRONOUNISH = {"it", "that", "there", "here", "what", "let", "he", "she", "who", "where", "this", "how"}
CODE_START = {"import", "package", "using", "from", "def", "const", "#include"}


def start_value(t):
    """Activation at the first token of a document, from the token's shape."""
    s = t.strip()
    cs = [c for c in t if not c.isspace()]
    if not cs:
        return -0.8
    c = cs[0]
    if s in CODE_START:
        return -6.0
    if s in ("//", "/*"):
        return 2.0
    if s.startswith("<|"):
        return -2.9
    if ord(c) >= 0x2E80:
        return -4.0
    if c.isdigit():
        return -2.4
    if t[:1] == " ":
        return -2.2
    return -1.4


def step(carry, prefix, upstream):
    t = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        return None, start_value(t)
    if t == "··":
        return None, -5.5
    prev = prefix.token_strings[-2].strip().lower()
    if t in ("'s", "’s"):
        return None, 0.0 if prev in PRONOUNISH else 1.0
    if t in ("'", "’"):
        return None, 1.3 if prev.endswith("s") else 0.0
    if t == " " and len(prefix.token_strings[-2]) >= 2 and not prefix.token_strings[-2].strip():
        return None, -0.5
    return None, 0.0

programs.sol:
"""Recognize web-address landmarks and East Asian noun-linking particles.

The largest responses are the protocol separator and GitHub's domain ending.
Japanese の, Korean 의, and Chinese 的 get smaller positive responses.
Date digits following East Asian year/month markers are negative. A small
negative default at document starts and the label Title: are also modeled.
A 120-character suffix supplies context and resets at document boundaries.
Most other text is near zero; weaker lexical effects are not represented.
"""
import re
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ''
    else:
        tail = carry[1]
    s = prefix.token_strings[-1]
    value = -0.13 if not tail else 0.0

    if s == '://':
        if re.search(r'https?$', tail):
            value = 1.75
        elif tail.endswith('git'):
            value = 0.5
    elif s.strip() == 'www':
        value = 1.65 if tail.endswith('://') else 0.68
    elif s == '.com':
        if tail.endswith('github') and not tail.endswith('.github'):
            if tail.endswith('://github'):
                value = 4.5
            elif tail.endswith('"github'):
                value = 3.6 if tail.endswith('\\"github') else 4.1
            else:
                value = 3.1
        else:
            value = 0.18
    elif s == '.org':
        value = 0.18
    elif s == '.in' and tail.endswith('gopkg'):
        value = 2.3
    elif s == '/repos' and tail.endswith('api.github.com'):
        value = 1.96
    elif s == '@':
        local = re.search(r'[A-Za-z0-9_.+-]+$', tail)
        if local and any(c.isalpha() for c in local.group()):
            value = 1.18 if '.' in local.group() else 0.52
        else:
            value = -0.08
    elif s == 'の':
        value = 0.68 if tail else 0.13
    elif s == '의':
        value = 0.52
    elif s == '的':
        value = 0.29
    elif len(s) == 1 and s.isascii() and s.isdigit():
        date = re.search(r'(年|月|世紀|世纪)([0-9]*)$', tail)
        if date and len(date[2]) < 2:
            value = -1.25 if not date[2] else -1.0
        elif regex.search(r'\p{Script=Han}[0-9]{0,1}$', tail):
            value = -0.11
    elif s == ':' and tail == 'Title':
        value = 3.6

    return (doc, (tail + s)[-120:]), value

programs.haiku:
"""Layer 1, MLP down-projection component 4051: a web-address and genitive-particle detector.

What it does, in plain terms: its activation is near zero on almost every token, and
large only at a few kinds of token, each with a rough strength:

- the ".com" that closes "github" (github.com, raw.githubusercontent.com): strongest;
- the "://" right after "http", "https" or "ftp", and the "www" that follows "://";
- "/repos" in an API address such as api.github.com/repos;
- the "@" of an e-mail address, when it follows a plain word;
- the particles "の" (Japanese) and "的" / "의" (Chinese / Korean) that link a modifier
  to the noun after it: weak but frequent;
- the colon in the corpus artifact "<|endoftext|>Title:".

It is pushed slightly negative on a digit written straight after a Chinese year or
month character (年 or 月, as in "2014年1月"), and on the first token of each document.
Everything else is 0.
"""

READS = ()

SCHEMES = {"http", "https", "ftp"}
DIGITS = set("0123456789")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    # The first token of a document has no context: a small negative value.
    if len(prefix) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, -0.13
    prev = prefix.token_strings[-2]
    word = prev.strip().strip("\"'(-").lower()  # the previous token, without punctuation
    if tok == "://" and word in SCHEMES:
        return carry, 1.8
    if tok == ".com" and word.endswith("github"):
        return carry, 4.2
    if tok == ".com" and word.endswith("hub"):  # the "ithub" piece of "github"
        return carry, 3.1
    if tok.strip() == "www" and (prev == "://" or prev.strip() == "" or prev.endswith(("at", "("))):
        return carry, 1.5
    if tok == "/repos":
        return carry, 2.0
    if tok == "@" and prev.strip().replace(".", "").replace("_", "").isalnum():
        return carry, 1.5
    if tok == ":" and prev == "Title" and prefix.token_strings[-3:-2] == ["<|endoftext|>"]:
        return carry, 3.6
    if tok in DIGITS and prev in ("年", "月"):
        return carry, -1.1
    if tok == "の":
        return carry, 0.7
    if tok in ("的", "의"):
        return carry, 0.3
    return carry, 0.0

programs.sol:
"""An opening-token pulse, sustained while that token keeps repeating.

At every packed-document boundary (and row start), choose a pulse height from
recognizable token classes. Continue it over an unbroken run of the same
initial token; after the first different token, predict zero until reset.
Uniform-prefix probes retained the opening response, motivating the run rule.
Heights approximate lexical variation; small mixed-context values are omitted.
"""
import unicodedata

READS = ()
ARTICLES = {'a', 'an', 'the'}
PRONOUNS = set('you he she it we they me him her us them'.split())
DEMONSTRATIVES = set('this that these those'.split())
CONJUNCTIONS = set('and or but nor so yet for'.split())
PREPOSITIONS = set('in on at from by with as into over under about between '
                   'after before through'.split())
AUXILIARIES = set('is are was were be been being am do does did have has had '
                  'can could shall should will would may might must'.split())


def first_value(text):
    word = text.strip()
    lower = word.lower()
    # Conventional openings of code snippets (without a preceding space).
    if text == 'package':
        return 25.84
    if text in {'import', 'from'}:
        return 13.85
    if text == 'def':
        return 9.97
    if text == 'using':
        return 5.51
    if text.startswith('<|') and text.endswith('|>'):
        return 3.12
    if text == '#include':
        return -0.62
    if text.startswith('//'):
        return 7.5
    if text.startswith('/*'):
        return 8.0 if '\n' in text else 1.5
    if text.startswith('#!'):
        return 7.9
    if text == r'\n':
        return 11.48
    if not word:
        if text == '\n':
            return 2.9
        if text == '\n\n':
            return 1.34
        return -1.9 if text == '\t' else -0.3
    if word.isdecimal():
        return -0.73
    if word == '#':
        return 7.82
    if word == '··':
        return 7.0  # Paired middle dots, often repeated as a filler/leader.
    if all(unicodedata.category(c)[0] == 'P' for c in word):
        if '\n' in text:
            return 2.85 if text.count('\n') == 1 else 1.1
        if word in {'.', ':'}:
            return 0.15
        if word == '(' and not text[0].isspace():
            return 5.58
        return 2.5
    if '\ufffd' in word:
        return 3.5  # Possibly an incomplete UTF-8 character.
    if not word.isascii():
        return 2.0
    if lower in ARTICLES:
        if word == 'A':
            return 0.5
        return 5.35 if word[0].isupper() else 2.9
    if word in {'I', 'We'}:
        return 8.5  # Capitalized first-person pronouns.
    if lower in PRONOUNS:
        return 4.5 if word[0].isupper() else 2.4
    if lower in DEMONSTRATIVES:
        return 3.9 if word[0].isupper() else 1.25
    if lower == 'of':
        return -0.7
    if lower == 'to':
        return 5.2
    if lower in CONJUNCTIONS:
        return 2.0
    if lower in PREPOSITIONS or lower in AUXILIARIES:
        return 1.5
    if word.isalpha():
        if word.isupper() or len(word) == 1:
            return 3.3
        if word.istitle():
            return 2.4 if len(word) <= 4 else 1.1
        return 1.5
    return 2.0


def step(carry, prefix, upstream):
    document = int(prefix.document_ids[-1])
    token = int(prefix.token_ids[-1])
    if carry is None or carry[0] != document:
        height = first_value(prefix.token_strings[-1])
        return (document, token, height), height
    _, opening_token, height = carry
    if opening_token == token:
        return carry, height
    # A missing token in the carry marks a run that has already ended.
    return (document, None, 0.0), 0.0

programs.haiku:
"""Component layers.1.mlp.down_proj:4052: a "first token of a document" feature.

It is silent inside a document and fires at a document's first token (the token after
<|endoftext|>, or the first token of a packed row). Its size depends on that token:
  - programming keywords and comment openers that start a file are strongly positive
    (`package` most of all, then `from`, `import`, `def`, `#`, `//`);
  - English sentence openers are positive: pronouns and articles (`The`, `I`, `We`),
    modal verbs and `to` (` can`, ` will`, ` to`), and single capital letters;
  - most other words are mildly positive; digits are slightly negative; camelCase
    property names after a space (` paddingRight`, ` onClick`) and words such as ` name`,
    ` value`, ` else` are negative.
The model's attention cannot tell a token from the document's first token while every
earlier token in the document is that same token (for example a long run of `··`). So the
program keeps the same prediction for such repeats, as the component does.
Values are class means over training documents' first tokens; a per-token table would
explain more of the first-token variance, but these classes are the readable part.
"""

import re

READS = ()

# Programming keywords that open a file when they have no leading space, with typical values.
FILE_OPENERS = {
    "package": 25.0, "from": 14.0, "import": 14.0, "def": 10.0, "namespace": 10.0,
    "const": 8.0, "use": 8.0, "using": 5.5, "int": 6.0,
}
PRONOUNS = {"The", "I", "We", "It", "This", "He", "She", "They", "You", "To", "My", "Our"}
FUNCTION_WORDS = {"to", "can", "will", "would", "should", "could", "might", "must", "may",
                  "the", "an", "and", "in", "with", "is", "has", "be", "it", "he", "we"}
IDENTIFIER_WORDS = {"name", "value", "else", "like", "key", "type", "text"}


def start_value(s):
    """Activation predicted for a token that is the first token of its document."""
    if s.startswith("<|"):
        return 3.1  # chat / end-of-text markers
    c = s.lstrip(" ")
    if s in FILE_OPENERS:
        return FILE_OPENERS[s]
    if s.startswith(" ") and c in FILE_OPENERS:
        return 0.0  # the same keyword mid-line means nothing
    if s.startswith(("#!", "//", "/*")) or s == "#":
        return 8.0  # comment and shebang openers
    if "\n" in s or "\r" in s:
        return 2.5
    if re.fullmatch(r"\d+", c):
        return -0.7
    if s.startswith(" ") and re.fullmatch(r"[a-z]+[A-Z][A-Za-z]*", c):
        return -3.0  # camelCase after a space: CSS / JS property names
    if s in PRONOUNS:
        return 5.7
    if re.fullmatch(r"[A-Z]", c):
        return 3.0
    if re.fullmatch(r"[A-Z][A-Za-z]*", c):
        return 1.9
    if s.startswith(" ") and c in FUNCTION_WORDS:
        return 4.0
    if s.startswith(" ") and c in IDENTIFIER_WORDS:
        return -4.0
    if s.startswith(" ") and re.fullmatch(r"[a-z]+", c):
        return 1.0
    if re.fullmatch(r"[a-z]+", c):
        return 2.6
    if c and ord(c[0]) > 0x2FF:
        return 2.1  # non-Latin scripts
    if c and not any(ch.isalnum() for ch in c):
        return 2.5  # punctuation and symbols
    return 1.6


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        # A document's first token: remember it, and that the document so far is just it.
        return (token, True), start_value(token)
    first, uniform = carry
    uniform = uniform and token == first
    # Later in a document, it responds only while every token so far is the first token.
    return (first, uniform), (start_value(token) if uniform else 0.0)

programs.sol:
"""A sparse approximation of the component's negative aboutness/depiction cue.

The strongest training examples link a text or depiction to its subject.
Recognize topic prepositions and description verbs; use dictionary senses of
previous words and a short trace of written works to strengthen some readings.
Dependence/contemplation phrases are weaker. Most past verb forms are weaker
than present/-ing forms. 'So on' and 'meaning of' are positive exceptions.
Other tokens predict zero. Fine-grained lexical and contextual variation is
intentionally omitted.
"""
from functools import lru_cache
import re
import wordnet

READS = ()

# These are subject-matter prepositions, including several translations.
TOPIC = {
    'on': .74, 'upon': 1.07, 'about': .83,
    'regarding': .81, 'concerning': .81,
    'sur': .81, 'sobre': .81, 'på': .81, 'على': .81,
    'о': .65, 'об': .65, 'про': .65, 'über': .65,
}

@lru_cache(None)
def bases(word):
    return frozenset(wordnet.base_forms(word)) | {word}

@lru_cache(None)
def nouns(word):
    """Dictionary senses, not a grammatical parse of the sentence."""
    if not word.isascii() or not word.isalpha():
        return False, False, False, False, False
    cats = wordnet.categories(word)
    work = wordnet.is_a(word, 'writing') or wordnet.is_a(word, 'narrative')
    image = wordnet.is_a(word, 'representation')
    constraint = (wordnet.is_a(word, 'rule') or
                  wordnet.is_a(word, 'restriction') or
                  bool(bases(word) & {'limit', 'legislation', 'requirement'}))
    return ('noun.communication' in cats, 'noun.cognition' in cats,
            work, image, constraint)

@lru_cache(None)
def description(word):
    b = bases(word)
    if b & {'depict', 'portray'}:
        strength = 1.2
    elif b & {'show', 'describe', 'represent', 'illustrate'}:
        strength = .35
    elif b & {'mention', 'indicate', 'discuss'}:
        strength = .25
    elif b & {'explain', 'feature'}:
        strength = .12
    else:
        return 0.
    if word.endswith('ed') or word == 'shown':
        strength *= .3
    elif word.endswith('ing'):
        strength += .35
        if b & {'show', 'describe', 'illustrate'}:
            strength += .4
    elif word.endswith('s'):
        strength += .28
    if word == 'showed':  # active past, unlike the participle 'shown'
        strength = .45
    return strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.)
    _, previous, work_trace = carry
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    comm, thought, work, image, constraint = nouns(previous)
    p = bases(previous)
    strength = TOPIC.get(w, 0.)
    if strength:
        if s.strip()[0].isupper():
            strength -= .14
        if not s.startswith(' '):
            strength -= .25
    if w == 'on':
        strength += .1 * comm + .1 * thought + .15 * (work or image)
        strength += 1.0 * constraint
        if p & {'base', 'depend', 'dependent', 'rely', 'effect', 'impact', 'go'}:
            strength = .08
        if previous == 'so':
            strength = -.35
    elif w == 'about':
        strength += .35 * comm - .15 * thought
        strength += 1.3 * max(float(work), work_trace)
        if p & {'think', 'worry', 'care', 'excited', 'passionate'}:
            strength = .22
    elif w == 'of':
        strength = .12 * (work or image)
        if p & {'meaning', 'significance'}:
            strength = -.65
    elif w == 'how':
        strength = .1
        if p & {'show', 'describe', 'illustrate', 'demonstrate', 'about', 'on', 'of'}:
            strength += .37
    else:
        verb = description(w)
        if verb:
            strength = verb + .35 * (work or image)
            if s.strip()[0].isupper():
                strength *= .5
            if w == 'show' and previous in {'a', 'the', 'this', 'that', 'tv', 'radio'}:
                strength = .08

    # Downweight matching fragments inside a larger word.
    continuation = bool(previous and s and s[0].isalpha())
    if continuation:
        strength *= .25
    match = re.search(r'([^\W\d_]+)$', previous + s)
    word = match.group().lower()[-80:] if match else ''
    work_trace *= .65
    if previous and s and not s[0].isalpha():
        work_trace = max(work_trace, float(work))
    return (doc, word, work_trace), -float(strength)

programs.haiku:
"""Candidate 4: words that link a text, talk, picture or work to its subject.

Negative activation on the word that introduces what a text, talk, book or picture is
about or depicts ("book about", "articles on", "chronicles", "dedicated to", "photos of").
Near zero for "depends on" / "based on", which name a dependence, not a subject.
Small positive on "meaning of" and on "by" after a passive verb.
"""
READS = ()

# Verbs and prepositions that introduce a subject, with typical activation.
TOPIC_WEIGHT = {
    " about": -1.0, " on": -0.8, " upon": -1.0, " regarding": -0.9, " concerning": -1.0,
    " describing": -1.1, " describe": -0.7, " describes": -1.0, " depict": -1.5,
    " depicts": -1.5, " portrays": -1.5, " portray": -1.5, " honor": -1.0, " honors": -1.5,
    " explores": -1.5, " chronicles": -1.5, " showing": -1.2, " shows": -0.7, " show": -0.4,
    " represents": -0.7, " represent": -0.6, " mentions": -0.4, " against": -0.3,
}
# Nouns of pictures, texts and events: "a photo of", "a memory of".
DEPICTION_NOUNS = {" photo", " pictures", " picture", " footage", " scenes", " memory",
                   " tales", " studies", " book", " books", " article", " essay", " paper"}
# Verbs that point to a recipient or topic: "dedicated to", "refers to".
POINTING_VERBS = {" dedicated", " devoted", " refers", " pertaining", " regards", " given",
                  " awarded", " issued", " devote", " dedicate"}
# Nouns for works and talks: a topic "on"/"about" after them is stronger.
TEXT_WORDS = {" book", " books", " article", " essay", " paper", " information", " comments",
              " talk", " talking", " focus", " focused", " write", " wrote", " written",
              " film", " story", " video", " problems", " paragraph", " photo", " memory"}
# Verbs and nouns that name a dependence: "depends on", "based on" are not about a subject.
DEPENDENCE_WORDS = {" depends", " depend", " depending", " based", " Based", " dependent", " relying"}

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    value = TOPIC_WEIGHT.get(cur, 0.0)
    if cur in (" on", " about"):
        if prev in DEPENDENCE_WORDS:
            value = 0.0
        elif prev in TEXT_WORDS:
            value *= 1.5
    elif cur == " of":
        if prev == " meaning":
            value = 1.0
        elif prev in DEPICTION_NOUNS:
            value = -1.0
    elif cur == " to" and prev in POINTING_VERBS:
        value = -1.2
    elif cur == " by" and prev.endswith("ed"):
        value = 0.15
    return carry, float(value)

programs.sol:
"""Estimate a mostly negative response to a standalone one-space token.

Line-leading blanks and blanks opening a quoted argument are strongest.
Written-out ``\\n`` boundaries have an especially large response.
Recent whitespace and indentation modulate their strength. Blanks within a
line are weak, except after numbers. Tool-call closing tags and an initial
``Title:`` label have separate negative responses. Other tokens predict zero.
"""
import re

READS = ()
OPEN_QUOTED_ARGUMENT = re.compile(r"""\([frbuFRBU]{0,2}\\*['"]$""")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, position = '', '', 0
    else:
        _, previous, tail, position = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token == ' ':
        spaces = tail.count(' ')
        newlines = tail.count('\n')
        last_line = tail.rstrip('\n').rsplit('\n', 1)[-1]
        indent = len(last_line) - len(last_line.lstrip())
        if OPEN_QUOTED_ARGUMENT.search(tail):
            value = -5.3 if tail[-2:-1] == '\\' else -7.0
        elif tail.endswith('\\n'):
            value = -7.7
        elif tail.endswith('\n'):
            if newlines <= 2:
                value = -5.8 if spaces <= 7 else -4.7
            else:
                value = -1.1 if indent == 1 else -3.6
        elif previous[-1:].isdigit():
            value = -1.05 if indent >= 2 else -0.25
        else:
            value = -0.01 if previous.startswith(' ') else -0.11
    elif token == '</tool_call>':
        value = -0.82
    elif position == 1 and previous == 'Title' and token == ':':
        value = -16.9
    return (doc, token, (tail + token)[-256:], position + 1), value

programs.haiku:
"""Document-initial 'Title:' spike, plus a small offset for the first token of a document."""
READS = ()

DIGITS = set("0123456789")
SENTENCE_OPENERS = {"The", " The", "I", "When", " When", "A", "To", "On", "By", "If", "This"}
CODE_OR_LIST = {"#", "package", "import", "###"}


def is_doc_start(prefix):
    n = len(prefix.token_ids)
    return n == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]


def step(carry, prefix, upstream):
    s = prefix.token_strings
    n = len(s)
    # the colon right after a document-initial "Title"
    if n >= 2 and s[-1] == ":" and s[-2] == "Title" and (n == 2 or prefix.document_ids[-2] != prefix.document_ids[-3]):
        return None, 5.7
    if is_doc_start(prefix):
        tok = s[-1]
        if tok in DIGITS or tok in SENTENCE_OPENERS:
            return None, -0.45
        if tok in CODE_OR_LIST:
            return None, 0.4
    return None, 0.0

programs.sol:
"""A contrast between short na- spellings and est/ast spellings.

Negative cues include nest, aesthetic/anesthetic stems, and a few Chinese
sensation words. Short na- fragments are positive, especially in a recent
West-Slavic spelling context. Alphabetic continuations retain 35% of the
previous response. These are approximate spelling rules, not a topic model.
"""
from functools import lru_cache
from anyascii import anyascii
import regex

READS = ()
SLAVIC_MARKS = frozenset("ąęłńśźżćčďěľĺňŕřšťůž")
SENSATIONS = {
    '麻': -7.8,       # hemp / numb
    '麻醉': -6.0,     # anesthesia
    '醉': -3.9,       # intoxicated
    '酔': -3.9,       # Japanese form
    '满足': -2.1,     # satisfied
    '滿足': -2.1,
}
ALPHABET = regex.compile(r'[\p{Latin}\p{Cyrillic}\p{Greek}]')


@lru_cache(maxsize=160000)
def spelling(s):
    return anyascii(s).lower()


def joins(cur, prev):
    return bool(cur and prev and ALPHABET.fullmatch(cur[0])
                and ALPHABET.fullmatch(prev[-1]))


def cue(cur, prev, slavic):
    if cur in SENSATIONS:
        return SENSATIONS[cur]
    if len(cur) >= 2 and not cur.strip('·'):
        return -0.77
    if not regex.search(r'[\p{Latin}\p{Cyrillic}]', cur):
        return 0.0
    s, p = spelling(cur), spelling(prev)
    c = s.strip()
    value = 0.0
    if c.startswith(('anesth', 'anaesth')):
        value -= 6.6
    if c.startswith('anast'):
        value -= 3.3
    if c in ('nest', 'nests'):
        value -= 2.67
    if c.startswith(('nested', 'nesting', 'nestle')):
        value -= 0.5
    if c.startswith(('aesthet', 'esthet')):
        value -= 1.0

    # A short na + consonant fragment, not a whole word such as "name".
    short_na = (c.startswith('na') and 3 <= len(c) <= 4
                and c.isalpha() and not any(ch in 'aeiouy' for ch in c[2:]))
    if short_na:
        if c[2] == 'd':
            value += 1.46 + 3.05 * slavic
        elif c[2] in 'sz':
            value += 0.30 + 2.57 * slavic
        elif c[2] in 'mkpg':
            value += 1.15 * slavic

    if not joins(cur, prev):
        return value
    if c.startswith('est') and p.endswith(('n', 'ana')):
        value -= 2.03
        if p.strip() in ('an', 'ana'):
            value -= 7.16
    if c.startswith('ast'):
        if p.endswith(('an', 'ana')):
            value -= 4.96
        elif p.endswith('n'):
            value -= 1.38
    if c in ('est', 'este') and regex.search(r'\p{Cyrillic}', cur):
        value -= 0.73
    if c.startswith('st') and p.endswith(('a', 'e', 'ae')):
        if not prev.isascii():
            value -= 0.38
        if prev[-1].lower() in 'äæě':
            value -= 2.2
        if p.endswith(('na', 'ne', 'nae')):
            value -= 0.34
    if p.endswith(('est', 'ast')) and c in ('het', 'hes', 'hetics'):
        value -= 2.4

    # The same na cue when n and the vowel are in different tokens.
    if p.strip() in ('n', 'en'):
        active = True
        if c == 'ad':
            value += 0.69
        elif c in ('as', 'ats', 'az', 'ash'):
            value += 0.79
        elif c in ('at', 'ath'):
            value -= 0.35
        elif c in ('ak', 'ag', 'am', 'ap', 'au', 'ay', 'ain', 'ade', 'agle'):
            value += 0.28
        elif c == 'a':
            value -= 0.15
        else:
            active = False
        if active:
            value += 1.22 * slavic
            if (prev.strip().isupper() and c in ('ad', 'as', 'at')
                    and regex.search(r'\p{Cyrillic}', prev)):
                value += 1.5
    if p.strip().startswith('na') and c in ('ad', 'd', 'as', 's', 'z', 'ze', 'za'):
        value += 0.38 + 0.32 * slavic
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, tail, age = '', 0.0, 1000
    else:
        _, prev, tail, age = carry
    cur = prefix.token_strings[-1]
    age = 0 if any(ch in SLAVIC_MARKS for ch in cur.lower()) else age + 1
    base = cue(cur, prev, age < 64)

    # Recognize split UTF-8 spellings too, without looking at a later token.
    if '\ufffd' in cur:
        same_doc = prefix.position > 0 and prefix.document_ids[-2] == doc
        recent = b''.join(prefix.token_bytes[-2:] if same_doc
                          else prefix.token_bytes[-1:])
        text = recent.decode('utf-8', errors='ignore')
        if (text and text[-1] in SENSATIONS
                and recent.endswith(text[-1].encode('utf-8'))):
            base = SENSATIONS[text[-1]]
        elif recent.endswith('麻'.encode('utf-8')[:2]):
            base = -7.5  # shared, still-incomplete hemp/wheat character prefix
    value = base + 0.35 * tail if joins(cur, prev) else base
    return (doc, cur, value, age), float(value)

"""Short spelling continuations of 'or', plus alternatives after 'or'.

Strong negative responses mark short 'orn' fragments, 'born/borne', and
an n-fragment completing an or-ending across a token boundary. Bare b/d/f
and some other short consonant fragments give a positive response instead.
Transliteration extends these spelling rules to other alphabets. The
cross-token rules avoid whitespace boundaries and mixed-case word starts.

Disjunctions are a second use of the same cue: 'or not/both/otherwise'
is negative, 'or if/perhaps/maybe' positive. 'Whether or not' is weaker.
A document-initial 'Title:' header is also negative. Everything else is
left at zero, rather than fitting the weak token-specific background.
"""
import re
from anyascii import anyascii
from functools import lru_cache

READS = ()


@lru_cache(maxsize=8192)
def roman(text):
    return anyascii(text).strip().lower()


def response(text, previous, before):
    word = text.strip().lower()
    last = previous.strip().lower()
    space = text[:1].isspace()
    if word in ('born', 'borne'):
        if word == 'born' and last[-1:] in ('(', ';', ','):
            return -9.0
        return -6.9 if space and text.strip().islower() else -9.0
    if word == '-born':
        return -6.5
    if word == 'airborne':
        return -7.8
    if word.startswith('orn') and len(word) <= 4:
        if last.endswith('b'):
            return -9.0
        return -3.6 if space else -4.8
    if word == 'ourn':
        return -9.0 if last.endswith('b') else -2.0
    if word == 'bourne':
        return -5.2
    if re.fullmatch('(?:[cfhpt]|th)orns?', word):
        return -2.0
    if word == 'icorn':
        return -5.7
    if not space and previous and not previous[-1].isspace() and not (
        text[:1].isupper() and not text.isupper()
    ):
        fragment = roman(text)
        prior = roman(before + previous)
        if fragment.startswith('n') and prior.endswith(('or', 'bour')):
            if prior.endswith('bour') and fragment == 'ne':
                return -10.5
            if fragment.startswith(('ner', 'nt')):
                return -8.5
            if len(fragment) == 2 and fragment[1] in 'eo':
                return -6.5
            if len(fragment) == 1:
                return -3.4 if text.isascii() else -6.8
            if (len(fragment) == 3 and fragment.startswith('ne')
                    and fragment[-1] in 'aeiou'):
                return -4.8
            return -2.5 if len(fragment) <= 3 else -1.0
        if prior.endswith('or'):
            # The strongest positive cases are individual consonants,
            # not arbitrary longer words starting with those consonants.
            if len(fragment) == 1 and (
                not text.isupper() or previous.strip().isupper()
            ):
                return {
                    'b': 2.5, 'd': 3.0, 'f': 2.3, 'p': 1.2, 'v': 1.2,
                }.get(fragment, 0.0)
            if fragment == 'sh':
                return 2.4
            if len(fragment) == 2 and fragment.startswith('b'):
                return 1.9
            if fragment == 'ton':
                return -3.0
        if prior.endswith(('orn', 'ourn')) and len(fragment) <= 3:
            if fragment == 'ith':
                return -5.5
            if fragment in ('ed', 'es'):
                return -4.0
            return -1.2
    if last == 'title' and not before and text == ':':
        return -4.1
    boundary = previous[:1].isspace() or not before or not before[-1:].isalpha()
    if boundary and word in ('no', 'non', 'não', 'нет', 'nicht') and last in (
        'o', 'ou', 'или', 'oder'
    ):
        return -4.0
    if (before.strip().lower() == 'or'
            and last in ('may', 'might') and word == 'not'):
        return -3.7
    if boundary and last == 'or':
        if word == 'not':
            if not text.strip().islower():
                return -3.0
            return -3.5 if before.strip().lower() == 'whether' else -9.5
        return {
            'both': -10.5, 'all': -4.7,
            'otherwise': -4.4, 'no': -3.0, 'nothing': -1.7,
            'none': -2.2, 'if': 2.7, 'perhaps': 2.3, 'maybe': 1.6,
        }.get(word, 0.0)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = ('', '')
    if carry is not None and carry[0] == doc:
        previous, before = carry[1:]
    text = prefix.token_strings[-1]
    value = response(text, previous, before)
    return (doc, text, previous), value

