"""Candidate 3: fires negatively on 'born' and on the second half of 'or'-phrases
(whether or not, part or all, one or both, or otherwise, or two, or none)."""
READS = ()

BORN = {"born", "-born"}
ORN_PIECES = {"orn", "orne", "orns", "orno", "thorn"}
OR_SECOND = {"not": -10.0, "all": -7.0, "both": -6.0, "otherwise": -5.0,
             "two": -2.0, "none": -2.0, "any": -1.0, "no": -1.0}

