"""Fires on an evaluative or quality adjective right after the article 'a' or 'an'
("it is a good idea", "an easy way", "a great place", "a promising start"), strongest for
'good', 'easy', 'great'. Weaker on such an adjective after 'the most', and on the words
'only', 'first', 'best', 'main', 'correct' after 'the' ("the only one"). It also gives a
weak signal on the noun right after such an adjective, and a slightly negative value on
the first token of a document."""
READS = ()

QUALITY = {
    " good", " great", " easy", " useful", " nice", " perfect", " bad", " better", " possible",
    " important", " effective", " ideal", " valuable", " valid", " fun", " common", " major",
    " significant", " safe", " powerful", " direct", " long", " straight", " pretty", " huge",
    " hard", " natural", " beautiful", " fast", " special", " strong", " wrong", " suitable",
    " favorite", " correct", " clear", " simple", " difficult", " interesting", " popular",
    " okay", " necessary", " apt", " welcome", " odd", " tough", " clever", " sensible",
    " pointless", " deep", " pricey", " comfortable", " promising", " remarkable", " holistic",
    " lesser", " dominant", " preferred", " integral", " fair", " likely", " excellent",
    " awesome", " amazing", " solid", " reliable", " practical", " quick", " cheap", " unique",
    " rare", " real", " dangerous", " efficient", " healthy", " wise", " relatively",
}
TOP = {" good", " great", " easy", " perfect", " nice", " useful", " ideal", " valuable", " effective"}
ORDINAL = {" only", " first", " best", " last", " next", " main", " correct", " primary", " top", " leading"}
ARTICLES = {" a", " an", " A", " An"}

def step(carry, prefix, upstream):
    t = prefix.token_strings
    d = prefix.document_ids
    if len(t) < 2 or d[-1] != d[-2]:
        return carry, -0.25  # first token of a document
    prev, cur = t[-2], t[-1]
    if cur in QUALITY:
        if prev in ARTICLES:
            if cur in TOP:
                return carry, 2.0 if prev != " an" else 2.4
            return carry, 1.2 if prev != " an" else 2.4
        if prev == " most":
            return carry, 1.0
        return carry, 0.15
    if cur in ORDINAL and prev == " the":
        return carry, 0.55
    if len(t) >= 3 and t[-3] in ARTICLES and t[-2] in QUALITY:
        return carry, 0.25  # the noun after 'a good'
