"""Sparse spelling and local-phrase cues, with zero elsewhere.

File suffixes, hexadecimal prefixes, and lexical (not auxiliary) 'do'
are the positive cues modeled here, grouping file formats rather than fitting
each suffix separately. Certain numeral continuations are negative.
We leave smaller, unrelated lexical responses unmodeled.
At document starts, typography supplies a separate coarse estimate; this
estimate continues across an opening run of identical tokens.
"""
import re
import wordnet

READS = ()

PROGRAM_SUFFIXES = {
    '.rs', '.py', '.go', '.java', '.js', '.ts', '.cpp', '.php',
    '.sh', '.vue', '.mod',
}
DOCUMENT_SUFFIXES = {'.txt', '.pdf', '.md', '.yml', '.yaml', '.json', '.list'}
ARCHIVE_SUFFIXES = {'.jar', '.zip'}
MODALS = {'can', 'could', 'would', 'should', 'will', 'may', 'might', 'must'}


def initial(token):
    """Opening typography, not a lookup of arbitrary opening words."""
    bare = token.strip(' ')
    if token and not bare:
        return 1.55 if len(token) == 1 else 3.0
    if token == '\t':
        return -2.75
    if '\n' in token or token.isspace():
        return -1.42 if token == '\n' else -.8
    if re.fullmatch(r'\\[nrt"\\]+', token):
        return -6.5
    if re.fullmatch(r'#+|-', bare) or bare == '|' or token == ' *':
        return 2.0
    if re.fullmatch(r'_{2,}', bare):
        return 3.0
    if re.fullmatch(r'\^{2,}', token):
        return -5.9
    if re.fullmatch(r'[a-z]', bare):
        # A spaced 'a' is normally the indefinite article, not a letter.
        return 0.0 if token == ' a' else (-2.4 if token[0] == ' ' else -3.7)
    if re.fullmatch(r'[A-Z]', token):
        return -.32
    if re.fullmatch(r'[0-9]', token):
        return -.8
    if token in {')', ']', '}', "'", '"', '“', '„'}:
        return -1.6
    return 0.0


def lexical_do(form, before):
    normalized = before.lower().replace('’', "'")
    words = re.findall(r"[a-z]+(?:'[a-z]+)?", normalized)[-6:]
    prev = words[-1] if words else ''
    if form == 'doing':
        return .9 if prev in {'of', 'in', 'by', 'from', 'while', 'when'} else .6
    if form == 'done':
        if prev in {'be', 'been', 'being'}:
            return .18
        perfect = any(w in {'have', 'has', 'had'} or w.endswith("'ve")
                      for w in words[-4:])
        return .8 if perfect else .2
    licensed = prev in {'to', 'cannot', 'lets', "let's", 'not'}
    if licensed or prev in MODALS or prev.endswith(("n't", "'ll", "'d")):
        return 1.25
    content = [w for w in words[-4:]
               if 'adverb' not in wordnet.parts_of_speech(w)
               and w not in {'the', 'a', 'an', 'all'}]
    if any(w in MODALS or w.endswith(("n't", "'ll", "'d"))
           for w in content[-2:]):
        return 1.15
    question = any(w in {'what', 'how', 'why'} for w in words)
    if question and any(w in {'do', 'did', 'does'} for w in words[-4:]):
        return 1.35
    if prev == 'me':
        return .95
    return .25 if prev == 'and' else -.025


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    before = '' if first else carry[1]
    opening = token if first else (token if carry[2] == token else None)
    value = 0.0
    if first:
        value = initial(token)
    elif opening is not None:
        value = carry[3]
    elif token in PROGRAM_SUFFIXES:
        value = .8
    elif token in DOCUMENT_SUFFIXES:
        value = .4
    elif token in ARCHIVE_SUFFIXES:
        value = .65
    elif token in {'py', 'rs', 'go', 'java', 'js', 'ts'} and before.endswith('.'):
        value = 1.1
    elif (re.search(r'(?<![A-Za-z0-9])0$', before)
          and re.fullmatch(r'x[0-9a-fA-F]*', token)):
        value = 1.25
    elif token == '0' and before.endswith('3'):
        value = -.36
    elif token == '1' and (before.endswith('\n') or before.endswith('\\n')):
        value = -.85 if before.rstrip('\n').endswith('：') else -.32
    elif (token.startswith(' ')
          and token.strip().lower() in {'do', 'doing', 'done'}):
        value = lexical_do(token.strip().lower(), before)
    return (doc, (before + token)[-128:], opening, value), float(value)

