"""layers.1.mlp.down_proj:4060 -- a code-context detector.

What it does, in plain terms:
- At the first token of a document, or of a row (rows can start mid-document),
  the token is read alone, since nothing precedes it. The value depends only on
  the token:
  * indentation made of spaces only: +2 (code indentation);
  * programming vocabulary (C/Java/Rust/Go keywords and types such as
    `unsigned`, `static`, `struct`, `uint`, `async`, `docker`): +1.2;
  * words starting with "#", and lowercase words after a tab: +1;
  * whitespace containing tabs or newlines: -1;
  * single letters, digits: -1; ALL-CAPS words: -0.7; quote, backslash or
    markup characters: -0.8; non-ASCII text: -0.3; pure punctuation: -0.2;
  * anything else: 0.
- Elsewhere it fires on a source-code file suffix written as its own token
  (`.go`, `.py`, `.rs`, `.ts`, `.java`, ...): +0.7, the way a filename ends.
  It also fires on the bare verb " do" after "to", "can", "not", "could" and
  similar words (as in "to do this"): +1.3.
Everything else is 0.
"""
import re

READS = ()

TECH = set("""
int char float double long short unsigned signed void bool static extern struct
typedef enum union auto volatile register inline sizeof return if else for while
switch case break goto class public private protected import export function var
let def fn impl pub mut type interface object string array list dict map set new
this self json node docker socket pragma final abstract override virtual template
namespace using package module uint byte atomic tensor vector async await try
catch throw throws pointer parser global mesh vertex
""".split())

SOURCE_SUFFIXES = set(""".go .py .rs .ts .js .mod .java .jar .sh .yaml .yml .json
.xml .spec .cpp .php .vue .md .properties""".split())


# words after which a bare verb "do" follows ("to do", "can do", "not do", "n't do")
BARE_BEFORE = {"to", "can", "could", "should", "would", "will", "must", "not", "'t", "may", "might"}


def start_value(token):
    t = token.lstrip("\t.").lower()
    if t in TECH and not token.startswith(" "):
        return 1.2
    if token.lstrip(" \t").startswith("#"):
        return 1.0
    if token.startswith("\t") and token[1:].isalpha() and token[1:].islower():
        return 1.0
    if token.strip() == "":
        return 2.0 if set(token) == {" "} else -1.0
    if re.fullmatch(r"[0-9]+", token) or re.fullmatch(r"[a-zA-Z]", token.strip()):
        return -1.0
    if re.fullmatch(r"[A-Z][A-Z_]+", token.strip()):
        return -0.7
    if any(c in token for c in '"\\<>&'):
        return -0.8
    if any(ord(c) > 127 for c in token):
        return -0.3
    if all(not c.isalnum() for c in token):
        return -0.2
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first:
        return None, start_value(token)
    if token.strip() in SOURCE_SUFFIXES and token.strip() != "":
        return None, 0.7
    if token == " do" and prefix.token_strings[-2].strip().lower() in BARE_BEFORE:
        return None, 1.3
    return None, 0.0

