"""Approximate separator and short-predicate responses.

Backslashes following path/namespace segments receive positive values. Other
escapes and double-backtick tokens receive smaller, shape-dependent values.
In English, degree
words after linking verbs are positive, while short impersonal predicates
("it's time/important/possible", "that's all") are negative. The rules use
character shapes and a bounded left context, not token-id lookup. Most other
tokens receive zero; token-specific background responses are not modeled.
"""
import re

READS = ()

MODIFIERS = (
    r'not|really|very|quite|also|now|just|still|always|probably|even|yet|often|'
    r'so|too|much|far|perhaps|indeed|certainly|obviously|almost|never|ever|'
    r'about|past|finally|already|then|usually'
)
TAIL = r'(?:\s+(?:' + MODIFIERS + r')){0,3}\s*$'
# A form of "be", possibly followed by a few modifiers.
COPULA = re.compile(
    r"(?:\b(?:is|are|was|were|be|been|being|am|isn't|isn’t|wasn't|wasn’t)"
    r"|['’`](?:s|re|m))" + TAIL
)
IMPERSONAL = re.compile(
    r"\b(?:it|this|that)(?:\s+(?:is|was|be)|['’`]s|"
    r"\s+(?:may|might|could|should|would|will|must|can)\s+(?:not\s+)?be)"
    + TAIL
)
QUESTION = re.compile(r"\b(?:is|was|isn['’]?t|wasn['’]?t)\s+it" + TAIL)
LINKING = re.compile(
    r'\b(?:looks?|looked|seems?|seemed|feels?|felt|feeling|becomes?|became|'
    r'gets?|got|getting|grows?|grew|growing|makes?|made|making)' + TAIL
)
CAUSATIVE = re.compile(r'\b(?:make|makes|made|making)\b[^.!?,;\n]{1,45}$')
SEGMENT = r'[A-Za-z](?:[A-Za-z_0-9.-]*[A-Za-z0-9])?'
PATH = re.compile(SEGMENT + r'(?:\\{1,2}' + SEGMENT + r')+$')
WINDOWS_PATH = re.compile(
    r'\b[A-Za-z]:\\{1,2}[A-Za-z0-9_. -]+'
    r'(?:\\{1,2}[A-Za-z0-9_. -]+)*$'
)
NAMESPACE = re.compile(
    r'(?:\b(?:namespace|use|new|extends|implements|instanceof)|'
    r'@(?:param|var|return|throws|expectedException))\s+'
    r'\\*[A-Za-z_][A-Za-z_0-9\\]*$'
)
# Keep mathematical backslash commands out of the path-separator branch.
TEX = re.compile(
    r'\\(?:math\w*|text\w*|frac|begin|end|display\w*|left|right|'
    r'[lr]angle|[lg]eq|cdot|nabla|Sigma|delta|in|notin|sum|int|sqrt|'
    r'(?:sq)?subset(?:eq)?|(?:big)?cup|cap)\b'
)
ENGLISH = {
    'more', 'most', 'time', 'important', 'possible',
    'better', 'best', 'all', 'like', 'well', 'some', 'no', 'always', 'also',
    'same', 'exactly', 'necessarily',
}
PREPOSITIONS = {'of', 'in', 'on', 'for', 'to', 'with', 'from', 'at', 'by', 'as', 'than'}


def separator_value(token, left, previous):
    end = previous.rstrip()[-1:]
    namespace = bool(NAMESPACE.search(left))
    if token.strip('\\'):
        if namespace:
            return 0.27
        if token.startswith('\\x'):
            return 0.15
        if previous.endswith('\\') or end == '`':
            return 0.34
        if any(c.isalpha() for c in token):
            return 0.15 if end.isdigit() else -0.03
        return 0.08
    if namespace:
        return 7.1
    line = left.rsplit('\n', 1)[-1]
    escape_letter = previous in {'n', 't', 'r', '\\n', '\\t', '\\r'}
    if not escape_letter and (
        WINDOWS_PATH.search(line) or (PATH.search(left) and not TEX.search(left[-120:]))
    ):
        return 5.5
    if end.isalpha():
        if escape_letter:
            return 2.2
        math = bool(TEX.search(left[-120:])) or any(c in left[-80:] for c in '$^{}')
        if math:
            return 1.5 if '\\n' in left[-80:] else 0.3
        return 2.3 if len(previous) <= 3 else 3.1
    if end in ')]}' and end:
        return 0.75 if '\\n' in left[-80:] else 0.12
    if end == ';':
        return -0.41
