        elif word == '大致':
            value = 3.7
        elif word.startswith('致') and word != '致':
            value = 2.2 if word in ('致电', '致敬') else 0.3
        elif (len(word) > 2 and word != '而导致') or word == '兴致':
            value = 0.8
    elif '緻' in word:
        value = 5.5 if word == '緻' else 2.5
    elif '至' in word:
        if word.startswith('甚至'):
            value = 4.25 if word == '甚至' else 2.6
        elif word in ('至于', '至於'):
            value = 3.5
        elif word == '至':
