"""Recognize compact clusters of common quotation marks.

Mixed quote types, escapes, and empty strings produce positive values; quoted
punctuation produces less. Closing syntax weakens a cluster. A quote-ending
previous token adds a local response. Other tokens are predicted near zero.
The history resets at each document boundary. This is a partial explanation:
non-quotation lexical responses are not modeled.
"""
READS = ()
QUOTES = "'\"`‘’“”„"
# Ordered pairs: a quotation mark inside a different sort of quotation.
MIXED = {
    ('single', 'double'): 5.0,
    ('double', 'single'): 2.7,
    ('backtick', 'double'): 3.5,
    ('double', 'backtick'): 1.5,
    ('backtick', 'single'): 2.9,
    ('single', 'backtick'): 2.0,
}


def family(char):
    if char in "'‘’":
        return 'single'
    return 'backtick' if char == '`' else 'double'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    carry = (doc, text)
    quotes = [i for i, c in enumerate(text) if c in QUOTES]
    if not quotes:
        return carry, -0.001
    value = 0.0
    if len(quotes) >= 2:
        i, j = quotes[:2]
        a, b = family(text[i]), family(text[j])
        middle = text[i+1:j]
        mixed = a != b
        if mixed:
            value = MIXED[a, b]
            if middle.strip('\\'):
                value *= 0.3
        elif a != 'backtick':
            if len(quotes) >= 3 and text[i:quotes[2]+1] == text[i]*3:
                value = 1.2 if a == 'single' else 0.0
            elif not middle:
                value = 0.75 if a == 'single' else 1.4
            elif not middle.strip('\\'):
