        elif '.' in lead:
            value *= 0.7
        if '\n' in tail or '\r' in tail:
            value *= 0.35 if mixed else 0.05
        elif any(c in ')]}' for c in tail):
            value *= 0.6 if mixed else 0.05
        elif ',' in tail:
            value *= 0.9 if mixed else 0.25
        elif tail:
            value *= 0.8 if mixed else 0.2

