"""Predict a lexical 'for' response with grammatical and formatting cues.

There are also independent responses to translations of 'for', dictionary
keys, object receivers, printf conversions, and the digit 4 in identifiers.
A small quote/bracket tracker distinguishes dictionary keys from values.
Strengths are calibrated on training rows. Literal escaped newlines also
count as line breaks for the local grammatical rules. All other tokens
receive zero; document boundaries reset the suffix and bracket state.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
VALUES = {
    'other': 0.0, 'for': 0.67, 'for_function': 0.3, 'for_verb': 0.53,
    'for_adjective': 0.51, 'for_title': 0.74, 'for_selected': 0.2,
    'for_wait': -0.2, 'for_known': -0.11, 'for_punctuation': 0.25,
    'loop': -0.21, 'for_unspaced': 0.14, 'For': -0.06, 'FOR': 0.53,
    'pour': 1.64, 'Pour': 1.05, 'para': 0.62, 'other_translations': 0.58,
    'italian_per': 1.82, 'middle_dots': 1.16, 'object_open': 0.92,
    'double_key': 1.72, 'single_key': 1.17, 'set_item': 1.0,
    'indented_quote': 0.5, 'include_quote': 0.39, 'self_line': 1.27,
    'self_code': 0.64, 'self_elsewhere': 0.23, 'receiver': 0.91,
    'receiver_parameter': 0.45, 'this_arrow': 1.39, 'printf_s': 1.57,
    'printf_d': 1.94, 'printf_v': 1.88, 'diff_range': 1.6,
    'four_identifier': 0.66, 'four_digit': -0.1,
}
FUNCTION_WORDS = set('and or but that which who you we he she they it '
                     'me us him her them this these those'.split())
FOR_SELECTORS = set('look search ask need allow account hope wish '
                    'responsible suitable'.split())


@lru_cache(maxsize=4096)
def grammar(word):
    return set(wordnet.base_forms(word)) | {word}, wordnet.parts_of_speech(word)


def italian(text):
    words = re.findall(r'[^\W\d_]+', text.lower())[-12:]
    scores = {lang: sum(zipf_frequency(w, lang) for w in words)
              for lang in ('it', 'en', 'es', 'fr', 'pt')}
    return scores['it'] > max(scores[l] for l in scores if l != 'it')


def category(s, tail, stack):
    tail = tail.replace('\\n', '\n').replace('\\t', '\t')
    w = s.strip()
    line_start = not tail.rsplit('\n', 1)[-1].strip()
    if s == ' for':
        if line_start:
            return 'loop'
        if re.search(r'[,;:]\s*$', tail):
            return 'for_punctuation'
        m = re.search(r'([A-Za-z]+)$', tail)
        previous = m[1] if m else ''
        base, pos = grammar(previous.lower())
        if previous.lower() in FUNCTION_WORDS:
            return 'for_function'
        if 'wait' in base:
            return 'for_wait'
        if base & {'know', 'ready'}:
            return 'for_known'
        if base & FOR_SELECTORS:
            return 'for_selected'
        if previous.istitle():
            return 'for_title'
        if 'adjective' in pos and 'noun' not in pos:
            return 'for_adjective'
        if 'verb' in pos and 'noun' not in pos:
            return 'for_verb'
        return 'for'
    if w == 'for':
        return 'loop' if '\t' in s else 'for_unspaced'
    if w in {'For', 'FOR'}:
        return w
    if w.lower() == 'pour':
        return 'pour' if w == 'pour' else 'Pour'
    if w.lower() == 'para':
        return 'para'
    if w.lower() in {'für', 'för', 'pentru'}:
        return 'other_translations'
    if s == ' per' and italian(tail):
        return 'italian_per'
    if s == '··' and (not tail or tail.endswith('··')):
        return 'middle_dots'
    if s in {'{"', ' {"', " {'", "{'", ':{"', '={"'}:
        return 'object_open'
    if s in {' "', " '", ' \\"', '\\"'}:
        if re.search(r'[,\{]\s*$', tail) and stack and stack[-1][0] == '{':
            if '"' in s:
                return 'double_key'
            return 'single_key' if stack[-1][1] else 'set_item'
        if line_start and tail:
            return 'indented_quote'
        if tail.endswith('#include'):
            return 'include_quote'
    if w == 'self':
        if line_start:
            return 'self_line'
        if re.search(r'(?:[=,(+:]|\b(?:if|return|in|not|yield))\s*$', tail):
            return 'self_code'
        return 'self_elsewhere'
    if s in {'(self', '(this'}:
        return 'receiver_parameter'
    if s in {'this', '\tthis', ' this'}:
        if line_start and tail or re.search(r'[$=({!;]\s*$', tail):
            return 'receiver'
    if s == '->' and re.search(r'\bthis$', tail):
        return 'this_arrow'
    if w in {'s', 'd', 'v'} and re.search(r'%[0-9.\-+]*$', tail):
        return 'printf_' + w
    if s == ' -' and tail.endswith('@@'):
        return 'diff_range'
    if s == '4' and tail:
        if tail[-1].isascii() and tail[-1].isalpha():
            return 'four_identifier'
        if tail[-1].isdigit():
            return 'four_digit'
    return 'other'


def scan(s, stack, quote, escaped):
    """Track brackets outside strings; a colon marks a dictionary, not a set."""
    for ch in s:
        if quote:
            if escaped:
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == quote or ch == '\n':
                quote = ''
        elif ch in '\"\'':
            quote = ch
        elif ch in '{[(':
            stack.append([ch, False])
        elif ch in '}])':
            if stack and stack[-1][0] == {'}': '{', ']': '[', ')': '('}[ch]:
                stack.pop()
        elif ch == ':' and stack:
            stack[-1][1] = True
    return stack[-24:], quote, escaped


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, stack, quote, escaped = '', [], '', False
    else:
        _, tail, stack, quote, escaped = carry
    s = prefix.token_strings[-1]
    value = VALUES[category(s, tail, stack)]
    stack, quote, escaped = scan(s, stack, quote, escaped)
    return (doc, (tail + s)[-240:], stack, quote, escaped), value

