"""layers.1.mlp.down_proj:4078, predicted from the text alone (no upstream reads).

What the component responds to, in plain terms:

1. Purpose/beneficiary prepositions meaning "for": English "for" in prose (~0.6),
   French "pour" (strong), Spanish/Portuguese "para", German "für", Russian/Bulgarian
   "за", and Italian "per" (strong, but only when the recent text is Italian; English
   "per unit" stays silent).
   The "for" that opens a code loop (indented "for (...)" / "for x in ...") is slightly negative.
2. Opening quotes of a key in a dict or JSON object: a quote that follows a comma
   inside an open "{" (e.g. {"name": "bash", "arguments": ...}, Python/JS dict literals),
   and the "{\"" that starts an object, most strongly inside tool-call JSON.
   The same quote after a comma inside a function call "(...)" stays silent.
3. "self" or "this" that begins a member access in code (indented, or after "=",
   "return", "(", etc.), and PHP "$this->".
4. A few format and syntax tokens: the "d" of a printf "%d", and a "4" right after letters
   (TLR4, Slf4j, NaBH4).

Everything else predicts 0. Activations are only tracked with a stack of open brackets
(reset at each document) and the last 40 tokens (for the Italian check).
"""

READS = ()

PURPOSE = {
    " for": 0.6,
    " FOR": 0.6,
    "for": 0.4,
    " pour": 1.7,
    " Pour": 1.5,
    " para": 0.5,
    " für": 0.6,
    " Für": 0.6,
    " за": 0.4,
}
ITALIAN_WORDS = {" di", " che", " della", " il", " gli", " alla", " nel", " sono", " delle", " degli"}
SELF_THIS = {" self", "(self", "self", " this", "this", "\tthis"}
OBJECT_OPEN = {'{"', ' {"'}
QUOTES = {' "', '"', " '", "'"}
CODE_PREV_END = ("=", "(", ":", "{", "[", ";", "!", "return", "->", "+")


def step(carry, prefix, upstream):
    # carry: the open-bracket stack and recent tokens, reset at each new document
    st = carry or {"doc": None, "stack": [], "recent": []}
    if prefix.document_ids[-1] != st["doc"]:
        st = {"doc": prefix.document_ids[-1], "stack": [], "recent": []}
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    p = prev.rstrip()
    inside = st["stack"][-1] if st["stack"] else ""
    indented = prev.strip() == "" and prev != ""

    value = 0.0
    if tok in (" for", "for", " For") and indented:
        value = -0.2  # 'for' opening a code loop
    elif tok == " per":
        if any(w in ITALIAN_WORDS for w in st["recent"]):
            value = 1.5  # Italian 'per' = 'for'
    elif tok in PURPOSE:
        value = PURPOSE[tok]
    elif tok in SELF_THIS:
        if indented or p.endswith(CODE_PREV_END):
            value = 1.1  # 'self.x' / 'this.x' starting a member access in code
    elif tok == "->" and prev.strip() in ("this", "self"):
        value = 1.4  # PHP $this->
    elif tok in ("d", "s", "v", "f") and p.endswith("%"):
        value = 1.8  # printf-style %d
    elif tok == "4" and prev[-1:].isalpha():
        value = 0.5  # the 4 in TLR4, Slf4j, NaBH4
    elif tok in OBJECT_OPEN:
        value = 0.9  # an object opening in JSON / dict
    elif tok in QUOTES and p.endswith(","):
