"""Definite scope and identity modifiers, plus a letter-pair side response.

Extent words (whole/full/entire) respond most strongly. Identity, precision,
and normal-state modifiers respond more weakly. A preceding definite or
possessive determiner makes them positive; indefinite and predicative uses
are usually negative. Other rules cover partitive 'all/rest of', C-F/C-G
acronym continuations, document headings, and middle-dot leaders. German
and Chinese extent expressions have a few analogous rules. Access phrases
("view the full") receive an extra boost. Only a short text suffix is
retained, and it is cleared at document boundaries.
"""
import re

READS = ()

# Strength in a definite noun phrase: these are scope/identity modifiers.
STRENGTH = {
    'whole': 6.0, 'full': 6.0, 'entire': 5.1, 'complete': 3.2,
    'exact': 3.8, 'true': 2.9, 'real': 2.5, 'actual': 2.2,
    'specific': 2.1, 'particular': 2.2,
    'general': 1.6, 'basic': 1.7, 'present': 1.75,
    'correct': 1.0, 'original': 0.75, 'regular': 1.0,
    'overall': 1.0, 'rest': 1.1, 'total': 0.6,
}
EXTENT = {'whole', 'full', 'entire'}
DEFINITE = {
    'the', 'this', 'that', 'these', 'those',
    'my', 'your', 'his', 'her', 'its', 'our', 'their', "'s", '’s',
}
INDEFINITE = {
    'a', 'an', 'any', 'some', 'no', 'every', 'each', 'another',
    'one', 'two', 'three', 'four', 'five', 'many', 'several',
}
PREDICATE = {
    'is', 'are', 'was', 'were', 'be', 'been', 'being',
    'not', 'as', 'so', 'very', 'more', 'quite', 'seems', 'seem',
    'always', 'still', 'too', 'practically',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = (old + token)[-96:]
    text = text.replace('\\n', '\n').replace('\\t', '\t')
    value = 0.0
    match = re.search(r'(?<!\w)([A-Za-z]+)$', text)
    if match:
        word = match[1].lower()
        before = text[:match.start(1)]
        prev_match = re.search(r"(['’]s|[A-Za-z]+|[0-9]+)\s*$", before)
        prev = prev_match[1].lower() if prev_match else ''
        # Pronoun + 's is a copula, not a possessive determiner.
        if re.search(r"\b(?:it|he|she|that|there|what)['’]s\s*$", before, re.I):
            prev = 'is'
        if prev == 'that' and word not in {'specific', 'particular', 'exact'}:
            prev = ''
        if word in STRENGTH:
            strength = STRENGTH[word]
            if prev in DEFINITE:
                value = strength
                if prev in {'this', 'that', 'these', 'those'}:
                    value *= 0.7 if word in EXTENT else 0.85
                if word == 'full' and prev != 'the':
                    value *= 0.65
                if word in {'whole', 'entire'} and prev == 'his':
                    value *= 1.25
            elif prev in INDEFINITE:
                if word in EXTENT or word == 'complete':
                    value = -(0.45 if word == 'whole' else 0.35) * strength
                elif word in {'exact'}:
                    value = 0.4
                else:
                    value = -0.15
            elif prev in PREDICATE:
                if word in EXTENT or word in {'complete', 'true'}:
                    value = -0.45 * strength
                elif word in {'real', 'present', 'correct', 'specific'}:
                    value = -0.5
                else:
                    value = 0.0
                if prev == 'very':
                    value *= 2.0
            else:
                value = -0.13 * strength if word in EXTENT else 0.05
                if word in {'specific', 'particular'}:
                    value = -0.25
                if word == 'exact':
                    value = 0.5
                if word in {'present', 'rest'} and prev == 'at':
                    value = -1.0
            if match[1][0].isupper() and prev not in DEFINITE | PREDICATE:
