            elif prev in {'entirety', 'bulk', 'majority', 'much', 'remainder', 'most'}:
                value = {'entirety': 3.3, 'bulk': 1.5, 'majority': 0.9,
                         'much': 0.9, 'remainder': 0.5, 'most': 0.35}[prev]
            elif prev in {'full', 'plenty', 'which'}:
                value = -0.6
            elif prev == 'lot' and 'whole lot' in before.lower():
                value = -2.0
        elif re.fullmatch(r'ganz(?:e|en|em|er|es)', word):
            value = 3.6 if prev in {'der', 'die', 'das', 'den', 'dem'} else 0.0
        elif word == 'lot' and prev == 'whole':
            value = -3.0

    # A distinct response to adjoining C-F and C-G letter sequences.
    part = token.strip()
    if re.search(r'[cC]\.?[fFgG]s?$', text):
        if part in {'F', 'G', 'f', 'g', 'gs'} and old.endswith(('c', 'C')):
            value = 1.3 if old.endswith('c') and part.isupper() else 5.8
        elif part == '.F' and old.endswith('C'):
            value = 4.0
        elif part.lower() in {'cf', 'cg'}:
            joined = old and old[-1].isalnum() and not token[0].isspace()
            value = 4.4 if joined else 1.4
    if part == 'F' and old.endswith('G'):
        value = 1.6
    if token == ':' and old == 'Title':
        value = 4.2
    if token == '#' and not old:
        value = -0.9
    if token == '··' and old.endswith('·'):
        value = -1.5
    if token in {'整个', '全部'}:
        value = 1.8
    if text.endswith('全集'):
        value = 5.8
    return (doc, text), float(value)

"""A small pattern-based approximation, not a token lookup.

Long, densely tokenized mixed-case ASCII streams and long hexadecimal strings
are negative; repetitive padding is exempt from the mixed-case rule. Other
rules cover split indefinite compounds, partitive phrases, page breaks,
middle-dot leaders, an initial Title: label, and document-initial case biases.
Most text stays near zero. Token-specific residual variation is not modeled.
"""
import re

READS = ()
# Also admit the URL-safe and percent-escaped spellings of encoded data.
ASCII_TAIL = re.compile(r'[A-Za-z0-9+/_%=-]+$')
HEX_TAIL = re.compile(r'[0-9a-fA-F]+$')
INDEFINITE = {'some': .84, 'every': .62, 'any': .28, 'no': .33}
PARTITIVES = {'all', 'both', 'either', 'neither', 'none', 'most',
              'some', 'few', 'many', 'several'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, 0, 0, '', '', 0, (), '')
    (_, pieces, chars, upper, lower, previous, before, position,
     recent, hex_run) = carry
    text = prefix.token_strings[-1]
    tail = ASCII_TAIL.search(text)
    if not tail or len(tail[0]) != len(text):
        pieces = chars = upper = lower = 0
        recent = ()
    if tail:
        word = tail[0]
        pieces += 1
        chars += len(word)
        upper += sum(c.isupper() for c in word)
        lower += sum(c.islower() for c in word)
        recent = (*recent[-11:], word)
    value = -.0025
    if tail and pieces >= 6 and chars / pieces < 2.:
        if upper / chars > .2 and lower / chars > .2:
            ramp = min(1., (pieces - 4) / 16.)
            digit_piece = sum(c.isdigit() for c in word) / len(word)
            value = ramp * (-.60 + .08 * digit_piece)
        # Repetitive padding is less like random binary data.
        if len(recent) == 12 and len(set(recent)) <= 6:
            value = -.0025

    hexadecimal = HEX_TAIL.search(text)
    if not hexadecimal:
        hex_run = ''
    elif len(hexadecimal[0]) == len(text):
        hex_run = (hex_run + text)[-64:]
    else:
        hex_run = hexadecimal[0][-64:]
    if (len(hex_run) >= 24 and any(c.isdigit() for c in hex_run)
            and any(c.isalpha() for c in hex_run)):
        value = -.2

    current = text.lower()
    root, earlier = previous.strip(), before.strip()
    suffix = current.strip()
    if suffix in ('one', 'thing', 'body', 'where'):
        value = -.025
        if root in INDEFINITE:
            value = INDEFINITE[root] if suffix == 'one' else .85
        elif suffix == 'where' and root == 'else':
            value = .9
    if current == ' of':
        if root in PARTITIVES:
            value = .10
        if root == 'one' and earlier in ('any', 'each', 'every', 'which'):
            value = -.35
        if earlier == 'any' and root in ('number', 'combination'):
            value = -.25
        if earlier == 'no' and root == 'amount':
            value = -1.25
    if current == ' as' and root == '*':
        value = .45
    if '\x0c' in text:
        value = .7
    if len(text) >= 2 and not text.strip('·'):
        value = -1.26 if position == 0 or (root and not root.strip('·')) else -.15

    if position == 0 and suffix and text.strip('·'):
        if text.strip().isupper():
            value = .025
        elif text.strip().istitle():
            value = -.20
        elif text.strip().islower():
            value = .05
        elif suffix.isdigit():
            value = -.05
        if current == 'title':
            value = -.39
    if position == 1 and previous == 'title' and text == ':':
        value = 1.68
    return (doc, pieces, chars, upper, lower, current, previous,
            position + 1, recent, hex_run), float(value)

"""A surface-form approximation to a grammatical-linker signal.

Japanese and Korean case/topic particles give positive values, weaker when
bundled into a longer token. Vietnamese temporal conjunctions are especially
strong; several Indonesian conjunctions also respond at word completion.
Common Korean verbal and question endings instead give negative values.
Other tokens are near zero, with a negative document-initial baseline.
"""
import re

READS = ()
JAPANESE = {
    'を': 1.42, 'は': 1.30, 'が': 1.14, 'も': 0.79,
    'に': 0.78, 'へ': 0.72, 'で': 0.56, 'と': 0.73,
    'や': 0.67, 'から': 0.57, 'まで': 0.67, 'より': 0.27,
    'の': 0.22, 'には': 0.73, 'では': 0.68, 'とは': 0.88,
    'にも': 0.53, 'でも': 0.31, 'からは': 0.60,
    'って': -0.29,
}
KOREAN = {
    '을': 1.49, '를': 1.40, '은': 0.97, '는': 1.0,
    '이': 0.85, '가': 1.10, '에': 0.94, '의': 0.20,
    '로': 0.54, '으로': 0.66, '와': 0.46, '과': 0.68,
    '에서': 0.62, '에게': 0.66, '도': 0.27, '만': 0.36,
    '부터': 0.48, '까지': 0.31,
}
# Time, condition, reason, and concessive conjunctions, by language.
VIETNAMESE = {'khi': 5.5, 'lúc': 5.0, 'nếu': 1.5, 'vì': 1.0}
INDONESIAN = {
    'ketika': 3.0, 'jika': 2.8, 'apabila': 3.5,
    'meski': 3.5, 'meskipun': 1.5, 'namun': 1.6,
}
WORD_END = re.compile(r'[^\W\d_]+$')


# Common Korean verb stems, for recognizing the relative-clause ending -는.
VERB_STEMS = set((
    '하 되 있 없 먹 받 주 보 듣 쓰 살 오 가 알 모르 '
    '만들 갖 돕 두 다듬'
).split())


def korean_verb(stem):
    if stem.endswith(('었', '았', '였')):
        stem = stem[:-1]
    return stem in VERB_STEMS or stem.endswith(('하', '되'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = b'' if first else carry[1]
    token = prefix.token_strings[-1]
    text = token.strip()
    value = JAPANESE.get(text, KOREAN.get(text, 0.0))
    if not value and len(text) > 1:
        if text.startswith('들') and text[1:] in KOREAN:
            value = 0.80  # plural noun suffix plus a case/topic particle
        elif text[-1] in 'をはがもにや':
            value = 0.50 * min(1.0, 2.5 / len(text))
        elif text.endswith('と') and text[-2] in 'るすだ」』':
            value = 0.45
        elif text in ('として', 'によって', 'に対して', 'にとって',
                      'について', 'により', 'ので', 'のに'):
            value = 0.38
    if token != text:
        value *= 0.65

    # Keep just a short trailing word, including unfinished UTF-8 characters.
    tail = (tail + prefix.token_bytes[-1])[-64:]
    match = WORD_END.search(tail.decode('utf-8', 'ignore'))
    word = match.group().lower() if match else ''
    # Distinguish Korean verbal/question endings from noun particles.
    if text == '가' and word.endswith('인가'):
        value = -7.3
    elif text == '니까' and word != text:
        value = -4.7
    elif text == '는' and korean_verb(word[:-1]):
        value = -1.8
    elif text == '다':
        # Hangul syllable coda 4 is ㄴ: recognize plain-present -ㄴ다.
        code = ord(word[-2]) if len(word) > 1 else 0
        final_n = 0xAC00 <= code <= 0xD7A3 and (code - 0xAC00) % 28 == 4
        value = -2.2 if final_n or word.endswith('는다') else -0.4

    if word in VIETNAMESE:
        value = VIETNAMESE[word]
        if text.lower() != word:
            value *= 1.3  # completion of a split conjunction, e.g. K + hi
    elif word in INDONESIAN:
        # The stronger effect is on a conjunction's completing fragment.
        value = 0.4 if text.lower() == word else INDONESIAN[word]
    elif text.lower() in ('while', 'whenever'):
        value = 0.16
    if first and (not value or text in JAPANESE or text in KOREAN):
        value = -0.18
    return (doc, tail), value

programs.haiku:
"""Function words that mark how a word relates to the rest of its sentence.

Layer 1's MLP writes a strong signal into the residual stream at certain function words:

- Japanese and Korean case particles, the small words after a noun that give its role in
  the sentence (を, は, が, に ... and 을, 를, 은, 는, 이, 가 ...). The component fires when
  it closes a noun phrase. を, 을, 를 and は are strongest; location, direction and
  "also/and" particles weaker.
- Korean particle pairs are chosen by the last syllable before them: 이/가, 은/는, 을/를,
  과/와 (consonant ending or vowel ending). When the pairing fits, the token is a real
  particle. When it does not, the same syllable is the end of a word, such as 작가 (writer),
  청와 (in 청와대) or 되었는 (a verb ending): the component goes negative there, strongly
  for 가, 와 and 는.
- Vietnamese "khi" (when) and "lúc" (at the time when): clause-linking time words, strongest
  of all (about 5 to 6). Also the Korean question ending 니까, which goes negative.

Everywhere else the component is silent.
"""

READS = ()

# Japanese particles: typical activation.
JAPANESE = {
    "を": 1.4, "は": 1.3, "が": 1.1, "に": 0.8, "も": 0.8, "へ": 0.8, "と": 0.7,
    "や": 0.7, "まで": 0.7, "では": 0.7, "には": 0.75, "から": 0.6, "で": 0.55, "にも": 0.55,
}
# Korean particles after a syllable whose final consonant fits them.
KOREAN = {
    "을": 1.5, "를": 1.45, "은": 1.15, "는": 0.95, "와": 1.0, "가": 1.05, "이": 1.2,
    "과": 0.7, "로": 0.85, "으로": 0.85, "에": 0.85, "에서": 0.65, "부터": 0.45,
    "도": 0.3, "만": 0.3,
}
# Particles written after a consonant ending (the others follow a vowel ending).
AFTER_CONSONANT = {"이", "은", "을", "과", "으로"}
# Activation when the particle does not fit the syllable before it: a word's own ending.
MISFIT = {"이": 0.1, "은": 0.15, "을": 0.5, "가": -3.5, "와": -4.5, "는": -2.0}


def has_final_consonant(ch):
    """True if the Hangul syllable `ch` ends in a consonant (has a batchim)."""
    return 0xAC00 <= ord(ch) <= 0xD7A3 and (ord(ch) - 0xAC00) % 28 != 0


def ends_with_word(text, word):
    """True if the text so far ends with `word`, which begins a word."""
    text = text.lower()
    if not text.endswith(word):
        return False
    return len(text) == len(word) or not text[-len(word) - 1].isalpha()


def step(carry, prefix, upstream):
    """Activation at this token: the strength of the function word it is, else 0."""
    token = prefix.token_strings[-1]
    text = prefix.text_prefixes[-1]
    if ends_with_word(text, "khi") or ends_with_word(text, "lúc"):
        return carry, 5.5
    if token == "니까":
        return carry, -4.5
    if token in JAPANESE:
        return carry, JAPANESE[token]
    if token not in KOREAN:
        return carry, 0.0
    before = prefix.text_prefixes[-2][-1:] if len(prefix.text_prefixes) > 1 else ""
    if before and has_final_consonant(before) != (token in AFTER_CONSONANT):
        return carry, float(MISFIT.get(token, KOREAN[token]))
    return carry, float(KOREAN[token])

programs.sol:
"""Technical spelling is usually negative; ordinary text stays near zero.

Track the current whitespace-delimited fragment. Slashes, underscores, dots
and hyphens in it signal paths or compound identifiers. Camel case, namespace
separators, and bare underscores also receive negative offsets. Document
starts have a coarse format-dependent baseline. Lowercase fibonacci has its
own strong response, unlike capitalized Fibonacci. This is a partial model.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, segment, age = carry if carry is not None else (None, '', -1)
    first = old_doc != doc
    if first:
        segment, age = '', 0
    else:
        age += 1
    s = prefix.token_strings[-1]
    w = s.strip()
    letters = any(c.isascii() and c.isalpha() for c in w)
    latin = w.isascii() and w.isalpha()
    before = segment if s and not s[0].isspace() else ''
    value = 0.0
    if letters:
        if w.startswith('_'):
            value -= 0.062
        elif w.startswith('/'):
            value -= 0.006
        elif w.startswith('.'):
            value -= 0.017
        elif w.startswith('-'):
            value -= 0.010
        if '/' in before:
            value -= 0.065
        if '_' in before:
            value -= 0.022
        if '.' in before:
            value -= 0.027
        if '-' in before:
            value -= 0.006
        if latin:
            if not s[:1].isspace():
                value -= 0.003
            if not (w.isupper() or w.islower() or w.istitle()):
                value -= 0.045
    elif w == '::':
        value -= 0.057
    elif w and set(w) == {'_'}:
        value -= 0.083
    if '\n' in s:
        value += 0.008
    if age == 1:
        value += 0.007
    if first:
        value += 0.08 if s.startswith('<|') else (
            -0.08 if w.isnumeric() else -0.095 if s[:1].isspace() else -0.18
        )
        if w.startswith('/*'):
            value = -0.95
        elif w.startswith(('"""', "'''")):
            value = -1.1 if '\n' in s else -0.82
    if w == 'fibonacci':
        value = -0.6
    text = segment + s
    parts = text.split()
    segment = '' if text[-1:].isspace() or not parts else parts[-1][-200:]
    return (doc, segment, age), value

"""Approximate relation-word and negation responses using short collocations.

English 'to' and 'by' are positive; listed complement constructions suppress
that response. Partitive 'of' is positive after quantifiers. Other branches
cover French negation, foreign prepositions, Java namespace roots, and markers.
A frequency comparison distinguishes Polish 'to' from English 'to'. Initial
tokens have coarse case/word-class baselines. Unlisted lexical effects are not
modeled. Only a bounded text tail is carried, reset for each document.
"""
import re
import inflect
import pycountry
import wordnet
from wordfreq import zipf_frequency

READS = ()

# Verbs selecting an infinitive, versus other fixed 'to' complements.
DESIRE_OR_ATTEMPT = {'want', 'like', 'try', 'ready'}
OBLIGATION = {'have', 'need'}
TO_COMPLEMENTS = set('''able unable easy hard difficult possible impossible
important necessary enough seem seems seemed supposed
meant intended designed decide decided aim aims aimed attempt attempts
ability order due according compared compare related relate relates relating
similar equal equals equivalent prior next close adjacent leading lead leads
led refers respect corresponding corresponds correspond opposed ought
be is are was were
relative closer closest free open better plans pursuant belong refer'''.split())
WEAK_TO_COMPLEMENTS = set('''used how way ways opportunity likely unlikely
expected required referred reference available subject continue continued
return returned response access willing tend tends tended potential'''.split())

# Small cross-language family of prepositions and negative particles.
RELATION_WORDS = {
    'bei': 0.75, 'über': 0.65, 'uber': 0.9, 'durch': 0.6, 'unter': 0.45,
    'zu': 0.31, 'mit': 0.28, 'nach': 0.35, 'von': 0.2,
    'par': 0.32, 'por': 0.4, 'pour': -0.24,
    'к': 0.2, 'без': 0.33, 'для': -0.15,
    'nicht': 0.28, 'ikke': 0.9, 'fur': 0.55,
}
DOMAIN_ROOTS = {'org', 'com', 'net', 'uk'} | {
    country.alpha_2.lower() for country in pycountry.countries
}
PATH_ROOTS = {'org', 'com', 'net', 'io', 'java', 'javax'}
_inflection = inflect.engine()
NUMBER_WORDS = {_inflection.number_to_words(n) for n in range(2, 21)}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    same_doc = (len(prefix.token_ids) > 1 and
                prefix.document_ids[-2] == prefix.document_ids[-1])
    previous = prefix.token_strings[-2].strip().lower() if same_doc else ''
    recent = carry if same_doc and carry is not None else ''
    value = 0.0

    if token == ' to':
        bases = {previous, *wordnet.base_forms(previous)}
        value = 0.55
        # Polish 'to' is usually a different grammatical word.
        if (zipf_frequency(previous, 'pl') >
                zipf_frequency(previous, 'en') + 1.5):
            value = 0.02
        elif bases & DESIRE_OR_ATTEMPT:
            value = -0.22
        elif bases & OBLIGATION:
            value = -0.12
        elif previous in TO_COMPLEMENTS:
            value = 0.0
        elif previous in WEAK_TO_COMPLEMENTS:
            value = 0.23
        elif previous in {'going', 'down'}:
            value = 1.1
        elif previous in {'back', 'out'}:
            value = 0.75
        elif wordnet.parts_of_speech(previous) == {'adjective'}:
            value = 0.3
    elif token == '-to':
        value = 0.75
    elif lower == 'to':
        value = 0.18 if token.startswith(' ') else 0.05
        if word == 'TO':
            value = 0.5
    elif token == ' of':
        value = -0.035
        if previous in {'any', 'many', 'some', 'each'}:
            value = 1.0
        elif previous in NUMBER_WORDS or previous in {'either', 'neither'}:
            value = 0.85
        elif previous in {'one', 'both'}:
            value = 0.53
        elif previous in {'all', 'most'}:
            value = 0.27
    elif lower == 'by' or token == '-by':
        value = 0.44 if word == 'by' else 0.35
        if previous in {'followed', 'divided', 'powered', 'multiplied',
                        'divisible', 'step'}:
            value = -0.02
    elif lower == 'not':
        value = 0.5
        if previous in {'do', 'or', 'need', 'why'}:
            value = 0.0
        elif previous in {'does', 'did', 'may', 'should', 'could', 'and'}:
            value = 0.23
        elif previous in {'would', 'have', 'has', 'had', "'m", "'s"}:
            value = 0.6
    elif word == 'pas':
        value = 2.35 if re.search(r"\b(?:ne\b|n['’])", recent, re.I) else 0.35
    elif word == 'nt' and previous in {
            'is', 'are', 'was', 'were', 'could', 'would', 'should', 'did', 'do'}:
        value = 2.3
    elif lower in {'dont', 'didnt', 'doesnt', 'isnt', 'wasnt', 'arent',
                   'werent', 'couldnt', 'wouldnt', 'shouldnt'}:
        value = 0.5 if lower == 'dont' else 1.2
    elif re.search(r'(?:^|[a-z])By(?:[A-Z]|$)', word):
        value = 0.48
    elif token.strip() in {'(!', '(!('}:
        value = 0.7
    elif token == ' !':
        value = 0.48
    elif lower == 'en':
        french = r'\b(le|les|des|du|une|ce|cette|dans|sur|avec|est|sont|pour)\b|[àèç]'
        value = 0.9 if re.search(french, recent, re.I) else 0.0
    elif token == '<|im_start|>':
        value = -0.067
    elif token == '</think>':
        value = 0.58
    elif previous == 'at' and lower == 'least':
        value = 0.56
    elif token.startswith(' ') and lower in RELATION_WORDS:
        value = RELATION_WORDS[lower]
    elif word in DOMAIN_ROOTS or word.lstrip('/') in PATH_ROOTS:
        if token.startswith('/'):
            value = 1.25
        elif previous in {'import', 'package', 'static', 'link'}:
            value = 1.5
        elif token == ' org':
            value = 1.3
    elif token in {' on', ' from', ' about', ' only', ' no'}:
        value = -0.075
    elif token in {' the', ' and', ' in', ' with', ' for', ' that', ' at'}:
        value = -0.03

    # At a document's first token there is no preceding linguistic context.
    if not same_doc:
        if word.isdecimal():
            value = -0.13
        elif word.isalpha():
            if lower in {'a', 'an', 'the', 'my', 'your', 'our', 'his', 'her', 'their'}:
                value = 0.2
            elif lower in {'i', 'you', 'he', 'she', 'it', 'we', 'they'}:
                value = -0.53
            elif word.istitle():
                value = -0.4
            else:
                value = -0.18 if word.islower() else 0.25
        elif not word:
            value = 0.23
        elif token == '<|im_start|>':
            value = -0.19

    # A bounded text tail is enough to recognize French ne ... pas. Reset at
    # document boundaries, even when documents are packed within a row.
    return (recent + token)[-100:], value

programs.haiku:
"""Layer 1 MLP down-projection, component 4084.

What it does: a small set of linking function words, chiefly English "to" and "by" (and "not",
and their counterparts in other languages), push this direction into the residual stream. How
strongly depends on the word just before the link:

  - "to" after a motion or "going" word ("going to", "bound to", "taken to"): strongest.
  - "to" after an object pronoun or particle ("take you to", "thank you to", "back to"): strong.
  - "to" after an infinitive-taking verb or adjective ("want to", "try to", "able to"): slightly
    negative. "to" after "due", "according", "related" etc. (fixed phrases): about zero.
  - "by" as a passive agent, after a past participle ("selected by", "seen by"): moderate.
  - "of" after a quantifier or number ("any of", "two of", "one of"): moderate.
  - "not": moderate. "to"/"by" in other languages (zu, par, por, durch, bei, mit): weaker.
  - Java/Maven package pieces (" org", "/org", "/java") and French "pas": large.
  - The first token of each document, which has no context: a small negative value.
Every other token predicts about 0. This explains the bulk of the component's large values; the
small diffuse variation on ordinary tokens is not modelled.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

MOTION = {"going", "bound", "taken", "down", "looking", "take", "took", "went", "go", "off"}
OBJECT_OR_PARTICLE = {"you", "me", "us", "them", "it", "him", "her", "up", "back", "out", "on",
                      "off", "down", ",", ")", "and", "time"}
INFINITIVE_HEADS = {"want", "wants", "wanted", "try", "tries", "tried", "trying", "ready", "need",
                    "needs", "needed", "have", "has", "had", "seem", "seems", "seemed", "like",
                    "able", "unable", "important", "is", "are", "was", "order", "way", "ability",
                    "designed", "intended", "necessary", "supposed", "easier", "used", "aims",
                    "attempt", "attempted", "hope", "hoped", "decided", "plan", "easy",
                    "difficult"}
FIXED_TO = {"due", "according", "related", "compared", "similar", "prior", "respect", "lead",
            "leading", "leads", "equal", "subject", "addition", "possible", "close", "enough"}
QUANTIFIERS = {"any", "many", "some", "each", "two", "three", "four", "five", "six", "one",
               "both", "most", "all", "much", "more", "several", "either", "none", "few", "total"}
PARTICIPLES = {"seen", "taken", "made", "given", "known", "built", "written", "shown", "done",
               "found", "led", "held", "set", "put", "born", "brought", "bought", "sold",
               "taught", "won", "chosen", "broken", "gone"}
OTHER_LANGUAGE_TO_BY = {"zu", "par", "por", "durch", "bei", "über", "mit", "med", "til", "om",
                        "av", "к", "von", "via"}
JAVA_PIECES = {" org", "/org", "/java"}
DOCUMENT_START = -0.14


def word(token: str) -> str:
    return token.strip().lower()


def activation(token: str, previous: str) -> float:
    """The component's value at a token, given the word before it ('' at a document start)."""
    w = word(token)
    if token in JAVA_PIECES:
        return 1.4
    if w == "pas":
        return 0.85
    if w in OTHER_LANGUAGE_TO_BY:
        return 0.25
    if w == "to":
        if previous in MOTION:
            return 0.9
        if previous in OBJECT_OR_PARTICLE:
            return 0.55
        if previous in INFINITIVE_HEADS:
            return -0.07
        if previous in FIXED_TO:
            return 0.0
        return 0.42
    if w == "by":
        return 0.45 if previous.endswith("ed") or previous in PARTICIPLES else 0.37
    if w == "of":
        return 0.58 if previous in QUANTIFIERS or previous.isdigit() else 0.0
    if w == "not":
        return 0.38
    return 0.0


def step(carry, prefix, upstream: Mapping):
    if len(prefix.token_ids) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, DOCUMENT_START
    previous = word(prefix.token_strings[-2])
    return carry, float(activation(prefix.token_strings[-1], previous))

programs.sol:
"""Pulses for URL syntax and some Chinese historical names.

HTTP(S) separators and the root github.com hostname are the main URL rules;
repeated separators weaken. Ordinary domain endings receive smaller values.
Chinese state-name characters receive a weak positive value. Inside book-title
brackets, a single Han token making the title-so-far a dictionary-recognized
canonical text receives a larger pulse; other non-novel classics get less.
Doubled middle-dot filler at the start of a document is negative. This is a
partial approximation, not a model of other lexical/contextual variation.
"""
import regex as re
import cedict

READS = ()
# Characters naming the seven Warring States, including traditional forms.
WARRING_STATES = frozenset('楚齐齊秦赵趙魏韩韓燕')
CANONICAL = (
    'five classics', 'four books', 'classics of confucianism',
    'analects', 'annals', 'i ching', 'classic of rites',
)
GITHUB = re.compile(r'(?<![\w.])github$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, True, None)
    _, tail, previous, urls, dots_only, title = carry
    token = prefix.token_strings[-1]
    value = 0.0

    if token == '://':
        scheme = previous.strip().lower()
        spaced = previous[:1].isspace()
        if scheme == 'https':
            value = 1.82 + 0.08 * spaced - 0.07 * min(urls, 3)
        elif scheme == 'http':
            value = 1.65 + 0.10 * spaced - 0.10 * min(urls, 3)
        elif scheme in ('ssh', 'git', 'ftp'):
            value = 0.55
        urls += 1
    elif token == '.com':
        value = 0.25
        if GITHUB.search(tail):
            value = 3.10
            if tail.endswith('://github'):
                value = 4.20
            elif tail.endswith('"github'):
                value = 3.95 if not tail.endswith('\\"github') else 3.40
        elif tail.endswith('githubusercontent'):
            value = 4.10
    elif token in ('.org', '.net', '.edu'):
        value = 0.33
    elif token == '/repos' and tail.endswith('api.github.com'):
        value = 1.67
    elif token == '/' and tail.endswith('github.com'):
        value = 0.65 if not tail.endswith('api.github.com') else 0.18

    # Character-level names of ancient states and classical books.
    if token in WARRING_STATES:
        value = 0.4
    if title is not None and len(token) == 1 and re.fullmatch(
        r'\p{Script=Han}', token
    ):
        name = (title + token).strip()
        if len(name) >= 2:
            gloss = ' '.join(cedict.glosses(name)).lower()
            if any(cue in gloss for cue in CANONICAL):
                value = 5.0
            elif re.search(r'\bclassic\b', gloss) and 'novel' not in gloss:
                value = 2.0
    for char in token:
        if char == '《':
            title = ''
        elif char == '》':
            title = None
        elif title is not None:
            title = (title + char)[-30:]

    dots_only = dots_only and bool(token) and not token.strip('·')
    if dots_only and len(token) >= 2:
        value = -1.63
    carry = (doc, (tail + token)[-96:], token, urls, dots_only, title)
    return carry, float(value)

"""South-Slavic spelling in a matching language context.

Word-frequency dictionaries supply spelling-prefix likelihoods, not a
learned token table. Language/country mentions give a persistent topic cue;
several distinctive completed words give a shorter-lived language cue.
These cues boost unfinished words that fit Serbo-Croatian/Slovenian or
Bulgarian/Macedonian spelling. Familiar English spellings get less weight.
A separate acute-accented c is quiet. Paired middle dots and bare carriage
returns have two explicit rules, independent of the language detector.
The many other token-specific fluctuations are left unexplained.
"""
import math
from functools import lru_cache
import pycountry
import regex
from wordfreq import top_n_list, zipf_frequency

READS = ()
LANGS = 'en de fr es it pt nl tr pl cs sk ru uk bg sh sl mk'.split()
GROUPS = [('sh', 'sl'), ('bg', 'mk')]
INDICES = [[LANGS.index(lang) for lang in group] for group in GROUPS]
COVERAGE = 100000

# Sum the frequencies of dictionary words that begin with each prefix.
TABLES = []
for language in LANGS:
    table = {}
    count = COVERAGE if language in ('sh', 'sl', 'bg', 'mk') else 30000
    for word in top_n_list(language, count):
        if word.isalpha():
            mass = 10 ** (zipf_frequency(word, language) - 9)
            for length in range(1, len(word) + 1):
                part = word[:length]
                table[part] = table.get(part, 0.0) + mass
    TABLES.append(table)

LABELS = []
for languages, countries in [
    (('sr', 'hr', 'sl', 'bs'), ('RS', 'HR', 'SI', 'BA')),
    (('bg', 'mk'), ('BG', 'MK')),
]:
    names = {pycountry.languages.get(alpha_2=code).name.lower()
             for code in languages}
    for code in countries:
        name = pycountry.countries.get(alpha_2=code).name.lower()
        names.update(part.split()[-1] for part in name.split(' and '))
    LABELS.append(names)
LABELS[0].update(('yugoslavia', 'yugoslav', 'yugoslavian', 'serbo', 'croat'))

@lru_cache(maxsize=200000)
def frequencies(word, complete):
    if not word:
        return (0.0,) * len(LANGS)
    if complete:
        return tuple(zipf_frequency(word, lang) for lang in LANGS)
    return tuple(9 + math.log10(max(table.get(word, 0.0), 1e-9))
                 for table in TABLES)

@lru_cache(maxsize=200000)
def distinctiveness(word, complete=False):
    fs = frequencies(word, complete)
    scores = []
    for group in INDICES:
        own = max(fs[i] for i in group)
        other = max(f for i, f in enumerate(fs) if i not in group)
        scores.append(max(0.0, min(3.0, own - 2.5, own - other)))
    return tuple(scores)


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc or '<|endoftext|>' in token:
        carry = (doc, '', [0.0, 0.0], [0.0, 0.0])
    _, word, topic, recent = carry
    topic = [cue * 0.998 for cue in topic]
    recent = list(recent)
    for ch in token:
        if ch.isalpha():
            if ch.isupper() and word and not word[-1].isupper():
                word = ''  # camel-case identifier boundary
            word = (word + ch)[-50:]
        else:
            if word:
                signals = distinctiveness(word.lower(), True)
                for j in range(2):
                    recent[j] = recent[j] * 0.85 + signals[j] * 0.15
                    if word.lower() in LABELS[j]:
                        topic[j] = 3.0
            word = ''
    carry = (doc, word, topic, recent)
    if token == '··':
        return carry, -2.17
    if token == '\r':
        return carry, 0.115
    if not word or token == 'ć':
        return carry, 0.0

    lower = word.lower()
    fs, fw = frequencies(lower, False), frequencies(lower, True)
    rare = max(0.0, min(1.0, (5 - max(fs[0], fw[0])) / 2))
    contexts = [max(t, min(3.0, max(0.0, r - 0.3) * 3))
                for t, r in zip(topic, recent)]
    cyrillic = bool(regex.search(r'\p{Script=Cyrillic}', token))
    j = 1 if cyrillic else 0
    own = max(fs[k] for k in INDICES[j])
    compatible = max(0.0, min(1.0, (own - fs[0] + 1) / 2))
    if j == 0:
        score = (0.33 * compatible + 0.033 * rare
                 + 0.29 * distinctiveness(lower)[0]
                 + 0.017 * distinctiveness(lower, True)[0])
    else:
        score = 0.23 * compatible + 0.047 * rare
    return carry, float(contexts[j] * score)

"""Approximate a response to short r+i spelling fragments, not word meanings.

Match ri within a token, across an r|i boundary, or in a short continuation
from the two preceding tokens. Treat rei similarly and transliterate other
scripts. Short endings involving p/b/m, g/d or f usually receive negative
values; preceding consonants, ending length and token boundaries modulate
these values. Most longer fragments stay near zero, while selected vowel
completions after r|i can be positive. Doubled middle dots and an escaped
carriage-return/newline pair have separate responses. Reset at documents.
This captures only part of the component's lexical and contextual variation.
"""
from functools import lru_cache
import re
from anyascii import anyascii

READS: tuple[str, ...] = ()

@lru_cache(20000)
def spelling(s):
    return anyascii(s).lower()


def response(tail, before, mode, nonlatin):
    n = len(tail)
    c = tail[:1]
    cluster = bool(before) and not re.search('[aeiouy]', before)
    if mode == 1:  # ri is inside this token
        if n <= 1:
            if c and c in 'pbm':
                if not before:
                    return -4.2 if c == 'p' else -2.5
                if not cluster:
                    return -0.06
                return -1.4 if len(before) == 1 else -3.2
            if nonlatin:
                return -0.12
            if not before:
                return {'g': -2.1, 'd': -1.85, 'f': -1.3}.get(c, -0.7)
            return -0.2 if cluster else -0.02
        if not before:
            return -0.9 if c == 'd' else (-0.2 if n <= 2 else -0.05)
        if cluster and c == 'p':
            if tail == 'ps' or tail.startswith('pp'):
                return -2.8 if len(before) >= 2 else -1.3
        if cluster and c == 'f' and n <= 2:
            return -0.7
        return -0.03
    if mode == 2:  # r and i straddle a token boundary
        if c == 'f':
            return -3.5 if n <= 3 else -0.6
        if c == 'p':
            return -4.8 if n <= 3 or tail.endswith(('ing', 'ed')) else -1.0
        if c and c in 'bm':
            return -3.0 if n <= 2 else -0.8
        if c and c in 'gd':
            return -1.5 if n <= 2 else -0.5
        if tail.startswith(('al', 'on', 'ous', 'um')):
            return 1.3
        if tail.startswith(('ne', 'nes')):
            return 0.8
        return -1.1 if not tail else -0.25
    # One further token continues the short syllable.
    if n <= 1 and c and c in 'pbmgdf':
        return -3.5 if nonlatin else -2.1
    if n <= 3 and c == 'p':
        return -1.2
    if n <= 5 and tail.endswith('ing'):
        return -0.7
    return -0.03


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, prev2 = ('', '') if carry is None or carry[0] != doc else carry[1:]
    cur = prefix.token_strings[-1]
    s, p, pp = spelling(cur), spelling(prev), spelling(prev2)
    state = (doc, cur, prev)
    if cur == '··':
        return state, -0.78
    if cur == '\\n' and (pp + p).endswith('\\r'):
        return state, -5.5
    s = s.replace('rei', 'ri')
    k = s.rfind('ri')
    if k >= 0:
        before, tail, mode = s[:k], s[k+2:], 1
    elif p.endswith(('r', 're')) and s.startswith('i'):
        before = p[:-2] if p.endswith('re') else p[:-1]
        tail, mode = s[1:], 2
    else:
        history = (pp + p).replace('rei', 'ri')
        k = history.rfind('ri')
        if not s or not s[0].isalpha() or k < 0 or len(history) - k > 5:
            return state, 0.0
        before, tail, mode = history[:k], history[k+2:] + s, 3
    before = re.search('[a-z]*$', before).group()
    return state, response(tail, before, mode, not cur.isascii())

programs.haiku:
"""Layer-1 MLP unit 4088: fires negatively on the punctuation that closes a code name
(snake_case / camelCase identifier or lowercase key) when a value or description follows:
`key":`, `name':`, `name:`, `name` (backtick). Strongest for snake_case and backticked names.
"""
import re

READS = ()

TICKS = {"`", "``"}
QUOTES = {'":', "':", '",', "',", '"', "'"}
COLONS = {":", " :", "::", "?:", ":\n"}
TABLE = {
    "tick": {"snake": -2.4, "camel": -1.7, "lower": -0.9, "other": -0.3},
    "quote": {"snake": -1.5, "camel": -1.2, "lower": -0.5, "other": -0.1},
    "colon": {"snake": -1.0, "camel": -0.9, "lower": -0.2, "other": 0.0},
    "other": {"snake": -0.2, "camel": -0.2, "lower": 0.0, "other": 0.0},
}


def _closer_kind(tok):
    if tok in TICKS:
        return "tick"
    if tok in QUOTES:
        return "quote"
    if tok in COLONS:
        return "colon"
    if tok[:1] in (" ", "\n", "\t") or tok in ("(", ",", "=", "|"):
        return "other"
    return None


def _name_kind(word):
    if "_" in word:
        return "snake"
    if re.search(r"[a-z][A-Z]", word):
        return "camel"
    if word.isalpha() and word.islower():
        return "lower"
    return "other"


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    kind = _closer_kind(tok)
    if kind is None:
        return None, 0.0
    before = "".join(prefix.token_strings[-5:-1])
    m = re.search(r"[A-Za-z0-9_]*$", before)
    word = m.group(0) if m else ""
    if not word:
        return None, 0.0
    return None, TABLE[kind][_name_kind(word)]

programs.sol:
"""An opening-token pulse, sustained through an initial run of identical tokens.

Its size depends on writing system, case, grammar classes and formatting.
Most later text is quiet; title labels and a few web/chat markers are exceptions.
This deliberately averages over the substantial word-specific variation.
"""
import regex

READS = ()

PERSONAL_PRONOUNS = set("i me we us you he him she her it they them".split())
DEMONSTRATIVES = {"this", "that", "these", "those"}
QUESTION_WORDS = set("who what when where why how which whom whose".split())


def opening_value(token):
    if token == '<|im_start|>':
        return -2.4
    if token == '<|endoftext|>':
        return 21.9
    if token == 'import':
        return -6.2  # opening a source-code import statement
    if token.isspace():
        if token == '\t':
            return 13.1
        if '\t' in token:
            return 5.4
        if '\n' in token or '\r' in token:
            return 5.5 if not token.startswith(' ') else 2.5
        if '\xa0' in token:
            return 6.1
        return 2.2
    word = token.strip()
    if len(word) >= 3 and set(word) == {'^'}:
        return 18.0  # a compiler's caret underline
    if len(word) >= 2 and set(word) == {'·'}:
        return 6.0  # decorative dotted leader
    if word in {'"""', "'''"} and '\n' in token:
        return 14.0  # a triple-quoted string opening
    if len(word) == 1 and word in '0123456789':
        return (6.57, 3.63, 1.65, 4.07, 2.92,
                2.10, 2.31, 3.23, 1.65, 2.49)[int(word)]
    if '\ufffd' in word:
        return 0.1
    if regex.search(r'\p{Script=Han}', word):
        return 2.6
    if word.isascii() and word.isalpha():
        spaced = token[0].isspace()
        lower = word.lower()
        if lower in {'a', 'an'}:
            return 4.7
        if lower == 'the':
            return 1.3 if spaced else 2.7
        if lower in PERSONAL_PRONOUNS | DEMONSTRATIVES:
            return 1.4 if spaced else 0.6
        if not spaced and word.istitle() and lower in QUESTION_WORDS:
            return 6.0
        if len(word) == 1:
            if word.islower():
                return 3.5 if spaced else 0.85
            return 1.6 if spaced else 2.0
        if word.istitle():
            return 3.6 if spaced else 4.0
        if word.isupper():
            return 2.9
        return 2.9 if spaced else 2.45
    return 2.35 if word.isalpha() else 1.9


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening_value(token)
        return (doc, token, True, 0, token, value), value
    _, opening, repeating, age, previous, pulse = carry
    age += 1
    repeating = repeating and token == opening
    value = pulse if repeating else 0.0
    if age == 1 and opening == 'Title' and token == ':':
        value = 40.48
    elif token == 'permalink' and previous.endswith('[#'):
        value = 2.3
    elif token == ' Tags' and previous.strip() in {'Show', 'Hide'}:
        value = 2.6
    elif token == '\n\n' and previous in {'<think>', '</think>'}:
        value = 0.3
    return (doc, opening, repeating, age, token, pulse), value

"""Approximate detector for short 'he' spelling fragments, not whole he-words.

Case, word boundaries, h-digraphs and recent function words distinguish stems
and names from the weak English pronoun response. Chinese river/ditch
spellings and 何, weaker in compounds, form another strong case. Byte-split spellings are recognized too,
including incomplete Korean he/heo syllables. Small secondary rules cover
engineering, initial comment headers, and repeated middle dots. Otherwise zero.
All state resets at document boundaries.
"""
import unicodedata
import regex
from functools import lru_cache

READS = ()
KANA = regex.compile(r"[\p{Script=Hiragana}\p{Script=Katakana}]")

# Recent function words distinguish English from German or unrecognized text.
GERMAN = frozenset('''der die das dem den des ein eine einer eines einen einem
und nicht sich von zu auf mit im ist aber auch für als nach noch bei aus'''.split())
ENGLISH = frozenset('''the and a an is was were this that his her it have has
would could be had said as for with but'''.split())


@lru_cache(maxsize=20000)
def describe(s):
    plain = ''.join(c for c in unicodedata.normalize('NFD', s)
                    if unicodedata.category(c) != 'Mn')
    stem = plain.lstrip(' \t\n\r./-_(\"\'')
    cue = s.strip().lower()
    language = int(cue in GERMAN) - int(cue in ENGLISH)
    kana = bool(KANA.search(s))
    return stem, language, kana


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    if fresh:
        previous, language, japanese, tail = '', 0.0, 0.0, b''
    else:
        _, previous, language, japanese, tail = carry
    s = prefix.token_strings[-1]
    raw = tail + prefix.token_bytes[-1]
    decoded = raw.decode('utf-8', 'replace')
    stem, cue, kana = describe(s)
    lower = stem.lower()
    value = 0.0

    if lower == 'he':
        if s[:1].isspace():
            if stem == 'he':
                value = 2.1 if language > 0.5 else (0.5 if language > -0.2 else -0.1)
                if any(c in previous for c in '=+*/\t'):
                    value = 1.8
            elif stem == 'He':
                value = 1.6
                if previous.rstrip().endswith(('.', '!', '?')):
                    value = 0.2 if language < -0.2 else 0.6
                elif previous.isspace():
                    value = 0.4
                elif previous.rstrip().endswith(('\"', '“', ':')):
                    value = 0.7
                if language > 0.5:
                    value = 2.1
            else:
                value = 0.55
        else:
            value = 1.2 if stem.isupper() else 0.8
            if stem == 'He' and language > -0.2:
                value = 1.5
            last = previous[-1:].lower()
            if last.isalpha():
                value = 2.8 if stem.isupper() else 1.9
                if last == 'a' and not stem.istitle():
                    value = 5.2
                elif last in ('t', 'c') or (last == 'p' and not stem.isupper()):
                    value = 0.05
            if fresh:
                value = 2.3
        if 'é' in s:
            value = 1.7
    elif (len(lower) == 3 and lower[:2] == 'he'
          and lower[2] in 'bkdlt'):
        value = 0.9
        if s.startswith(' ') and stem.islower():
            value = 0.25
    elif (previous.lower().endswith('h') and not s[:1].isspace()
          and lower.startswith('e') and len(lower) <= 3):
        value = 2.4 if lower in ('ed', 'el') else 0.25
        if lower == 'en':
            value = 1.25
        if lower == 'e' and ('é' in s or 'É' in s):
            value = 2.6
        if lower.startswith('er'):
            value = 0.4
        if previous[-2:].lower() in ('th', 'ch', 'ph', 'sh'):
            value = 0.3 if 'é' in s else 0.0
        if s.startswith('-'):
            value = 0.6

    if s in ('河', '沟'):
        value = 5.7
    elif '河' in s:
        value = 1.7 / max(1, len(s) - 1)
    elif s == '何':
        value = 0.65 if japanese > 0.2 or previous.endswith('如') else 5.2
        if previous.endswith(('幾', '几')):
            value = 1.5
    elif '何' in s:
        value = 1.8 if s == '任何' else 0.5
    elif s == 'ヘ':
        value = 0.8
    elif s == '工程':
        value = 1.6

    # The detector can fire before a byte-split character is complete.
    # Korean 허 = heo and 헤 = he share their first two UTF-8 bytes.
    if '\ufffd' in s:
        if raw.endswith('河'.encode()[:2]):
            value = 3.0
        elif raw.endswith('허'.encode()[:2]):
            value = 3.8
        elif decoded.endswith('河'):
            value = 7.7
        elif decoded.endswith('溝'):
            value = 3.1
        elif decoded.endswith('헤'):
            value = 4.0
        elif decoded.endswith('허'):
            value = 1.4
        elif decoded.endswith('힐'):
            value = 0.7

    # The same spelling with interleaved UTF-16 zero bytes.
    if s.lower() == 'e' and raw.lower().endswith(b'h\x00e'):
        value = 2.5

    # A source file's initial empty comment header is a separate strong case.
    if fresh and s == '//\n':
        value = 5.2
    if s == '··' and previous == '··':
        value = 1.1

    language = 0.9 * language + cue
    japanese = 0.9 * japanese + int(kana)
    return (doc, s, language, japanese, raw[-3:]), float(value)

programs.haiku:
"""Layer-1 MLP component 4090 (down_proj) of Qwen3-1.7B: a "he / hé" token detector.

It is nearly silent on most text. Its activation is set by the current token only:
- "he" spelled inside a longer word, with no space before it (he, He, HE, hé): a
  fragment such as "Sennheiser", "Mongan", "Helix", "Heros". Fires about 1.3-1.9.
- A capitalised "He" with a leading space (" He") fires weakly, about 0.35.
- Chinese characters read "hé": 河 (river), 黄河, 河北, 河流 (strongest, about 2-6), and
  何, 任何 (about 2). Otherwise 0.
The plain word " he" (with space, lower case) does not fire.
"""

READS = ()

HE_FRAGMENTS = {"he", "He", "HE", "hé", "Hé", "hà"}
RIVER = {"河", "黄河", "河北", "河流", "沟"}
HE_CHARS = {"何", "任何"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s in RIVER:
        value = 4.0
    elif s in HE_FRAGMENTS:
        value = 1.5
    elif s in HE_CHARS:
        value = 2.0
    elif s == " He":
        value = 0.35
    elif s == " HE":
        value = 0.5
    else:
        value = 0.0
    return None, value

programs.sol:
"""A sparse predictor of clause-joining words and source-code boundaries.

English 'and' is strongest after punctuation or at a capitalized beginning.
Other languages' conjunctions also fire; dictionary frequencies distinguish
ambiguous e/y/et from variables and English text. Code cues include indented
'if', comments, lower-case namespace qualifiers and opening string quotes.
Everything else stays near zero. Only a short, document-local suffix is kept.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# Translations of 'and' with relatively unambiguous spelling.
CONJUNCTIONS = {
    'und': 0.60, 'и': 0.30, 'і': 0.97, 'و': 0.86,
    'og': 0.88, 'och': 1.11, 'și': 0.89, 'és': 0.70,
    'oraz': 0.42, 'và': 0.36,
}
# These spellings also occur as variables, names, or words in other languages.
LANGUAGES = {
    'e': ('it', 'pt', 'es'), 'ed': ('it',), 'y': ('es',),
    'et': ('fr',), 've': ('tr',), 'i': ('pl', 'sh'),
    'si': ('ro',), 'ja': ('fi',), 'dan': ('id',),
}
QUOTE_AFTER = {':': 0.48, '=': 0.34, ',': 0.14,
               '(': 0.34, '[': 0.29, '{': -0.02}

@lru_cache(maxsize=20000)
def frequency(word, language):
    return zipf_frequency(word, language)

def foreign_context(tail, languages):
    """Are recent words more typical of the conjunction's language than English?"""
    words = re.findall(r'[^\W\d_]+', tail.lower())[-10:]
    words = [w for w in words if len(w) > 1]
    if not words:
        return False
    return max(sum(max(-3, min(3, frequency(w, lang) - frequency(w, 'en')))
                   for w in words) / len(words)
               for lang in languages) > 0.3

def predict(s, tail):
    word = s.strip()
    lower = word.lower()
    before = tail.rstrip()
    line = tail.replace('\\n', '\n').rsplit('\n', 1)[-1]
    line_start = not line.strip() or line.strip().isdigit()
    boundary = bool(s[:1].isspace()) or not tail or not tail[-1].isalnum()
    punct = bool(before) and before[-1] in ',;:.!?'

    if word.endswith('αι') and re.search(r'(?:^|\W)και$', tail + s):
        return 2.19  # Greek 'and', sometimes split into several tokens.
    if lower == 'and' and boundary:
        if word != 'and' or s == 'and':
            return 0.47 if word != 'and' else 0.45
        return 0.28 if punct else -0.03
    if lower in LANGUAGES and boundary:
        if foreign_context(tail, LANGUAGES[lower]):
            return 1.46 if punct else 0.97
        return 0.0
    if lower in CONJUNCTIONS and boundary:
        return CONJUNCTIONS[lower]

    if word == 'elif':
        return 0.65
    if word == 'if' and boundary:
        if not tail:
            return 0.43
        if line_start or re.search(r'\belse\s*$', before):
            return 0.85
        return 0.13 if before.endswith((';', '{', '}', ')', '(')) else 0.03
    if lower == 'not' and re.search(r'\bif\s*$', before):
        return 0.34
    if word in {'WHERE', 'JOIN', 'assert'}:
        return 0.25 if word == 'assert' else 0.42
    if word.startswith('//') and set(word) == {'/'}:
        return 1.13 if len(word) == 2 else 0.17
    if word.startswith('/**'):
        return 0.06
    if word.startswith('/*'):
        return 0.51
    if word == '#':
        if s.endswith('\n'):
            return -0.07
        if line_start and (s[:1].isspace() or line):
            return 1.08
        if line_start:
            code = re.search(
                r'\b(def|import|return|print|for|while)\b|[=;{}]|```', tail
            )
            return 0.91 if code else 0.25
        if s[:1].isspace():
            return 0.27
        return 1.41 if before.endswith('`') else -0.04
    if word == '--':
        return 0.87 if line_start else -0.03
    if word in {'&&', '||', '∧'}:
        return 0.37
    if word in {'::', '::{'} and not s[:1].isspace():
        match = re.search(r'[\w]+$', before)
        if match and match[0][0].islower():
            # Test-file selectors and Java method references aren't namespaces.
            if before.endswith('.py') or re.search(r'[A-Z]\w*\.\w+(?:\.\w+)*$', before):
                return 0.02
            return 1.60
        return -0.07
    if word in {'("', "('", '!("', '("%'}:
        return 0.06 if s[:1].isspace() else 0.42
    if word in {'="', "='"}:
        return 0.17
    if word in {'"', "'"} and s[:1].isspace():
        return QUOTE_AFTER.get(before[-1:], 0.02)
    return 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = predict(s, tail)
    return (doc, (tail + s)[-240:]), value

programs.haiku:
"""Clause-joining conjunctions, code comment/operator markers, and opening quotes (v5)."""
READS = ()

# "and" in other languages: fires on these whatever comes before.
FOREIGN_AND = {" et", " Et", " e", " und", " och", " og", " ja", " و", " și", " és", " dan",
               " y", " ve", " và", " oraz", " и", " ed", " si", " i"}
# English "and": fires mainly when it joins clauses, right after a comma.
ENGLISH_AND = {" and", " And", "And", " AND", "AND"}
# Comment and operator markers in code.
CODE_MARKS = {" //", "//", " #", "#", "::", "/*", " &&", " ||", "&&", "||", "--"}
IF_WORDS = {" if", "\tif", "if", " elif"}
QUOTES = {' "', " '"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if s in CODE_MARKS:
        value = 0.8
    elif s in FOREIGN_AND:
        value = 0.7 if prev.strip() == "," else 0.4
    elif s in ENGLISH_AND:
        value = 0.3 if prev.strip() == "," else 0.0
    elif s in IF_WORDS:
        value = 0.8 if prev.strip() == "" else 0.1
    elif s in ("('", '("'):
        value = 0.4
    elif s in QUOTES:
        # an opening quote that starts a value, as after a colon in JSON or a dict
        value = 0.5 if prev.endswith(":") else 0.1
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Approximate a sparse response to web-page furniture and license boilerplate.

Predict negative values at labels such as 'See also', 'View Full', and the
closing Apache limitations clause. Markdown subheadings following an early
page title get a stronger negative response, weakened by distance and earlier
subheadings. Some conventional UI labels and omission marks have positive
responses. Small character-class offsets approximate document starts; most
other tokens receive almost zero. This does not model the fine lexical background.
"""
import calendar
import math
import re

READS = ()

# Current token: (preceding text, response). These are conventional page labels.
LABELS = {
    ' Full': ('View', -1.15),
    ' Profile': ('View', -2.45),
    ' more': ('View', -0.80),
    ' More': ('View', -0.48),
    ' Question': ('View', -0.74),
    ' links': ('External', -0.29),
    ' timer': ('Show', -1.05),
    ' Tags': ('Show', -0.72),
    ' Recommended': ('##', -0.90),
    ' Posts': (' Recommended', -0.85),
    ' Logged': (' IP', -0.75),
    ' protected': ('email', 1.22),
    '.archive': ('web', 2.09),
    ' sites': ('Share on other', 0.40),
}
MONTHS = re.compile(r'\b(?:' + '|'.join(calendar.month_abbr[1:]) + r')\b')


def prose_words(text):
    # Ignore comment markers, line numbers, and printed newline escapes.
    text = text.replace('\\n', ' ').replace('\\t', ' ')
    return re.sub(r'[^A-Za-z]+', ' ', text).strip()


def initial_value(s):
    """Coarse context-free offsets, not a token lookup table."""
    u = s.strip()
    if s == '<|im_start|>':
        return 0.198
    if u and set(u) == {'#'}:
        return 0.40
    if not u:
        return -0.30
    if u.isdecimal():
        return -0.14
    if u.isascii() and u.isalpha():
        if len(u) == 1 and u.islower():
            return -0.48
        return -0.21 if s.startswith(' ') else -0.07
    return -0.03


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, tail, title, sections, nested = 0, '', None, 0, False
    else:
        _, pos, tail, title, sections, nested = carry
    line_start = not tail or tail.endswith('\n')
    value = -0.002

    if pos == 0:
        value = initial_value(s)
    elif s == ' also':
        value = 0.085
        if tail.endswith('See'):
            value = -1.28 if tail == 'See' or tail.endswith('\nSee') else -0.64
        elif tail.endswith('see'):
            value = -0.34
        elif tail.lower().endswith('you may'):
            value = -0.57
        elif tail.lower().endswith('you might'):
            value = -0.26
    elif s == ' License':
        if prose_words(tail).endswith('limitations under the'):
            value = -3.95 if re.search(r'[*#]|//', tail[-55:]) else -2.2
        elif tail.endswith(' MIT'):
            value = -3.66
        elif tail.endswith('distributed under the'):
            value = -1.10
        elif tail.endswith('See the'):
            value = -0.82
        elif tail.endswith('Creative Commons Attribution'):
            value = -0.70
    elif s in (' SOFTWARE', ' DAMAGE'):
        words = prose_words(tail)
        if s == ' SOFTWARE' and words.endswith('OTHER DEALINGS IN THE'):
            value = -1.5
        elif s == ' DAMAGE' and words.endswith('POSSIBILITY OF SUCH'):
            value = -0.95
    elif s in ('###', '####', ' ###', ' ####'):
        if line_start or s.startswith(' '):
            if re.search(r'\d[\d,]* views\s*$', tail):
                value = 0.10
            elif title is not None and not nested:
                value = -5.3 / (1 + (pos-title)/60)**0.65
                value /= 1 + 2.0 * sections
            elif tail.endswith('TAGS:\n\n'):
                value = -0.90
            elif MONTHS.search(tail[-40:]) or re.search(r'\d:\d\d', tail[-40:]):
                value = -0.80 / (1 + pos/80)**0.65
            else:
                value = -0.25 / math.sqrt(1 + pos/50)
    elif s == 'posted' and line_start:
        value = -5.3 if title is not None and sections == 0 else -1.25
    elif s == ' by' and tail.endswith('posted') and title is not None:
        value = -0.74
    elif s == '...' and line_start:
        value = 1.35
    elif s == ':' and tail == 'Title':
        value = 1.936
    elif s == ':' and tail.endswith('# Thread'):
        value = -0.70
    elif s == ' Profile' and tail.endswith('Community'):
        value = -0.65
    elif s in LABELS:
        previous, response = LABELS[s]
        if tail.endswith(previous):
            value = response

    # Remember an early top-level page title and subsequent heading hierarchy.
    if line_start and s == '#' and pos < 32 and title is None:
        title = pos
    if title is not None and tail.endswith('#') and not s.startswith(' '):
        title = None
    elif line_start and s.strip() in ('##', '###', '####', '#####'):
        sections += 1
        nested = nested or s.strip() == '##'
    carry = (doc, pos + 1, (tail + s)[-256:], title, sections, nested)
    return carry, float(value)
